// ── 2026-11-05 GrokBot「记忆交接」— 会话回合跑完自动沉淀交接包 ─────────────────
// 对齐 GrokBot 的记忆交接体验：多 agent 一轮协作结束后，把本轮结论沉淀为
// memory_handoffs 交接包（最后发言的 agent → 下一个执行者/群成员首位），下游
// agent 经 /api/memory/handoff/context 能读到，accept 后注入自己的上下文副本。
// 零 LLM：summary 规则式拼接（本轮 goal + 各 agent 产出首行）；开关沿用
// settings.memory.autoLearn（默认开）。任何失败静默 — 沉淀是 additive 增强。

/** 纯函数：组装交接包 payload。不满足沉淀条件（单 agent/空产出/autoLearn 关）返回 null。 */
export function buildRoundHandoffPayload(
  input: {
    groupId: string;
    turnSeq: number;
    goal: string;
    autoLearnOff?: boolean;
    speakers: Array<{ id: string; name: string; excerpt: string }>;
  },
): { shift_id: string; from_agent: string; to_agent: string; scope_key: string; task_type: string; summary: string } | null {
  if (input.autoLearnOff) return null;
  // 按 agent 去重：同一 agent 多次发言（重试/返工/回炉）只计一次，产出取最新
  // 一条，顺序按首次发言（执行序）。不自环：from=最后发言、to=首位——同一
  // agent 首末都是它（A,B,A）时 to 顺延到下一位不同 agent（createHandoff 禁
  // 自环，撞上会把整包静默丢掉）。
  const byId = new Map<string, { id: string; name: string; excerpt: string; first: number; last: number }>();
  input.speakers.forEach((s, i) => {
    if (!s.id || !s.excerpt) return;
    const prev = byId.get(s.id);
    if (prev) {
      prev.name = s.name;
      prev.excerpt = s.excerpt;
      prev.last = i;
    } else {
      byId.set(s.id, { id: s.id, name: s.name, excerpt: s.excerpt, first: i, last: i });
    }
  });
  const speakers = [...byId.values()].sort((a, b) => a.first - b.first);
  // 双方角色齐备才沉淀（单 agent 无交接语义）。
  if (speakers.length < 2) return null;
  const from = speakers.reduce((a, b) => (b.last > a.last ? b : a));
  const to = speakers.find((s) => s.id !== from.id)!;
  const summary = [
    input.goal ? `任务：${input.goal.slice(0, 100)}` : '',
    ...speakers.map((s) => `${s.name}：${s.excerpt.slice(0, 120)}`),
  ]
    .filter(Boolean)
    .join('；')
    .slice(0, 600);
  return {
    // shift_id 幂等锚：一回合一锚（nextChatTurnSeq 防撞号），同回合重复触发
    // 不重复建包（sinkRoundHandoff 落库前按 shift_id 查重）。
    shift_id: `chat:${input.groupId}:${input.turnSeq}`,
    from_agent: from.id,
    to_agent: to.id,
    scope_key: input.groupId.slice(0, 120),
    task_type: 'chat_round',
    summary,
  };
}

/** 薄壳：组 payload → createHandoff 落库。任何失败静默（additive 增强）。返回 Promise 供测试 await。 */
export function sinkRoundHandoff(input: {
  groupId: string;
  turnSeq: number;
  goal: string;
  speakers: Array<{ id: string; name: string; excerpt: string }>;
}): Promise<void> {
  return (async () => {
    // 动态 import（防循环依赖；主链路零感知）。
    const { getSetting } = await import('../../storage/settings');
    const { createHandoff, findHandoffByShift } = await import('../../storage/memory-handoff');
    const payload = buildRoundHandoffPayload({
      ...input,
      autoLearnOff: getSetting('memory.autoLearn') === false,
    });
    if (!payload) return;
    // shift_id 幂等锚：同回合已有交接包（无论 from/to）→ 不重复建包。
    if (findHandoffByShift(payload.shift_id)) return;
    createHandoff(payload);
  })().catch(() => {
    /* 沉淀失败不影响聊天主链路（SQLite 不可用等） */
  });
}

/**
 * 测试可见：本回合的交接锚编号 = max(hop turn_seq, 已用交接锚) + 1。
 * 无 hop 落库的回合（无边团队/记录失败降级）turn 号不被 agent_hops 预留，
 * 靠已用交接锚防撞号——撞号会让后一轮的交接包被幂等查重误跳过。
 */
export function nextChatTurnSeq(groupId: string): number {
  return Math.max(nextTurnSeq(groupId), maxShiftTurnAnchor(`chat:${groupId}:`) + 1);
}

/**
 * 取消一次挂起审批（拒绝收场）。图→博文流水线里新草稿顶替旧流水线时收掉
 * 旧审批门用；幂等（无此挂起 → false，不抛）。
 */
export function cancelPendingApproval(groupId: string, nodeId: string): boolean {
  const key = `${groupId}:${nodeId}`;
  const entry = pendingApprovals.get(key);
  if (!entry) return false;
  pendingApprovals.delete(key);
  try { entry.resolve('rejected'); } catch { /* settled */ }
  return true;
}

/**
 * 注册一次节点审批挂起，返回等决定的 Promise（决定路径①②③的单一注册真源）。
 * deps.approval.request 接线与回归测试共用。外部取消（用户插话换轮/停止生成）
 * 由 swapDagRun 拒收场；这里另挂 30 分钟兜底超时（与 run 超时同量级，避免永久
 * pending 占内存）——超时视作拒绝，审批 promise 永不悬挂。
 * meta（2026-11-09）：节点展示名/预览随条目存下，GET /:id/approvals/pending
 * 审批卡可见化用；缺省回落 nodeId（旧调用零改动）。
 */
export function registerPendingApproval(
  groupId: string,
  nodeId: string,
  meta?: { nodeName?: string; preview?: string },
): Promise<'approved' | 'rejected'> {
  return new Promise<'approved' | 'rejected'>((resolve) => {
    const key = `${groupId}:${nodeId}`;
    pendingApprovals.set(key, {
      resolve,
      nodeId,
      nodeName: meta?.nodeName?.trim() || nodeId,
      preview: (meta?.preview ?? '').trim(),
      createdAt: Date.now(),
    });
    setTimeout(() => {
      const entry = pendingApprovals.get(key);
      if (entry && pendingApprovals.delete(key)) {
        try { entry.resolve('rejected'); } catch { /* settled */ }
      }
    }, 30 * 60_000).unref?.();
  });
}

/**
 * GET /api/groups/:id/approvals/pending 出参（2026-11-09 挂起可见化）。
 * 条目对齐前端 PendingApprovalItem（ProductApp normalizeApproval）：
 * decideApproval 回投 POST /:id/approvals/:node_id → approvalDecisionHandler
 * 命中本注册表同一 key，批/拒闭环成立。now 注入供测试控时。
 */
export function listPendingApprovalItems(
  groupId: string,
  now: number = Date.now(),
): Array<Record<string, unknown>> {
  const items: Array<Record<string, unknown>> = [];
  for (const [key, entry] of pendingApprovals.entries()) {
    if (!key.startsWith(`${groupId}:`)) continue;
    items.push({
      approval_id: key,
      node_id: entry.nodeId,
      submitter_name: entry.nodeName,
      summary: entry.preview
        ? `${entry.nodeName}：${entry.preview.slice(0, 80)}`
        : `${entry.nodeName} 的执行等待人工审批`,
      waiting_seconds: Math.max(0, Math.round((now - entry.createdAt) / 1000)),
      kind: '人工审批门',
      target: entry.nodeName,
      detail: entry.preview,
      impact: '批准后该节点继续执行并交接下游；拒绝则本轮跳过该节点',
    });
  }
  return items;
}

// 测试可见:登记本轮 controller 并取消同 group 上一轮,返回本轮 controller。
export function swapDagRun(groupId: string, registry: Map<string, AbortController>): AbortController {
  registry.get(groupId)?.abort();
  // 2026-11-05 审批门 — 换轮即取消上一轮挂起的节点审批（视作拒绝收场）：
  // 用户插话/重发 = 放弃上一轮，审批 promise 不悬挂（executor 侧 blocked 收口）。
  for (const key of [...pendingApprovals.keys()]) {
    if (!key.startsWith(`${groupId}:`)) continue;
    const entry = pendingApprovals.get(key);
    pendingApprovals.delete(key);
    try { entry?.resolve('rejected'); } catch { /* settled */ }
  }
  const ac = new AbortController();
  registry.set(groupId, ac);
  return ac;
}

/**
 * 2026-11-04 群聊「停止生成」— 主动取消该群当前 fan-out 轮：
 *   1) abort 该群的 fan-out AbortController（DAG 路径 runTeamDagFanout 停止
 *      调度后续节点；串行路径 for-await 断流，上游 LLM call 一并取消）；
 *   2) 经 cancelRunSession 把该群互链 conversation 下所有 running gateway
 *      run 终结为 canceled（事件日志落 'aborted' 帧，timeline runs 状态
 *      立即翻终态 → 前端 busy 解除、Stop 按钮回到发送）。
 * 返回是否真的有东西被取消（幂等：无在跑轮 → false）。
 */
export function stopGroupFanout(groupId: string): boolean {
  const ctrl = activeDagRuns.get(groupId);
  let stopped = false;
  if (ctrl && !ctrl.signal.aborted) {
    ctrl.abort();
    stopped = true;
  }
  const conv = getConversationByGroup(groupId);
  if (conv) {
    for (const sessionId of listSessionsByConversation(conv.conversation_id)) {
      if (cancelRunSession(sessionId)) stopped = true;
    }
  }
  return stopped;
}

interface GroupRecord {
  group_id: string;
  agent_ids?: string[];
  // B2 — ChatMessageItem 是原 inline 形状的超集（多 message_id/timestamp），
  // toHistory 只读 sender_kind/content，不受影响。
  messages?: ChatMessageItem[];
  kind?: string;
  /** 2026-05-30 — 用户在群设置选的 CLI 工作目录(绝对路径)。空 = 用默认。 */
  workspace_dir?: string;
  /** 2026-06-03 — group 绑定的 team_id(Python 持久化)。有值且 team 可读时走 DAG 调度。 */
  team_id?: string | null;
}
interface AgentRecord {
  agent_id: string;
  name?: string;
  soul?: string;
}

/**
 * 判断是否应走 DAG 执行路径。可纯测试(无 I/O 依赖)。
 * group.team_id 有值 → true;缺失/null/空字符串 → false(串行降级)。
 */
export function shouldRunTeamDag(group: Pick<GroupRecord, 'team_id'>): boolean {
  return !!group.team_id;
}

// 1b（2026-06-12）— 群读写经 getGroupsBackend() 抽象：SF_GROUPS_BACKEND==='node'
// 直调 SQLite store，否则 HTTP 打 Python（现状）。下面三个薄封装保持原签名，
// 让 runFanout / timeline 等调用点零改动。agent 读取仍走 Python HTTP（pyGetAgent）。

import { PYTHON_BACKEND_URL } from '../../python-backend';
import {
  applyCraftMarkers,
  ingestProductAttachments,
  ingestProductMaterial,
  isCraftGroup,
  readCraftTeamRef,
} from '../../storage/craft-intake';
import { setupCraftTeam } from '../../storage/craft-team-setup';
import type { CraftAction } from '../../lib/craft-markers';

/** 读一个群（经群后端抽象）。返回蛇形 record（含 messages）或 null。 */
async function pyGet<T>(path: string): Promise<T | null> {
  // 兼容旧签名：本函数只用于群读取（path 形如 /api/groups/<id>）。提取 group_id
  // 后走后端抽象。其余路径（agent）请用 pyGetAgent。
  const m = /^\/api\/groups\/([^/]+)$/.exec(path);
  if (m) {
    const groupId = decodeURIComponent(m[1]);
    const g = await getGroupsBackend().getGroup(groupId);
    return (g as unknown as T) ?? null;
  }
  // 非群路径：HTTP 打 Python（agent 等）。
  try {
    const res = await fetch(`${PYTHON_BACKEND_URL}${path}`);
    if (!res.ok) return null;
    const json = (await res.json()) as { data?: T } | T;
    return ((json as { data?: T }).data ?? json) as T;
  } catch {
    return null;
  }
}

/**
 * 追加一条消息（经群后端抽象）。返回创建的 MessageItem（或 null）。
 * node 模式：直调 store 持久化，并把 agent/system 消息 publish 到 Node SSE 总线
 * （对齐 Python post_group_message 对 agent/system 的 publish_group_event）；user
 * 消息不 publish（前端已乐观渲染）。python 模式：HTTP 打 Python，Python 自己 publish。
 */
async function pyPostMessage(
  groupId: string,
  body: {
    content: string;
    sender_name: string;
    sender_kind: string;
    agent_id?: string;
    /** 2026-11-07 拖拽传图 — user 消息随行附件（持久化透传；agent/system 无）。 */
    attachments?: UserAttachment[];
  },
  opts: { noDispatch?: boolean } = {},
): Promise<unknown> {
  const created = await getGroupsBackend().appendMessage(groupId, body, opts);
  if (
    process.env.SF_GROUPS_BACKEND === 'node' &&
    (body.sender_kind === 'agent' || body.sender_kind === 'system')
  ) {
    const type = body.sender_kind === 'system' ? 'system.notice' : 'agent.message';
    // node store 暂未落 agent_id 列（groups-backend TODO）— publish 帧合并
    // body.agent_id 兜底，前端 U0 头像归属不因后端模式丢字段。
    const data = {
      ...body,
      ...((created ?? {}) as Record<string, unknown>),
    };
    if (body.agent_id && !('agent_id' in ((created ?? {}) as object))) data.agent_id = body.agent_id;
    publishGroupEvent(groupId, { type, data });
  }
  return created;
}

/** Map persisted group messages → dispatcher history (user/assistant; skip system). */
function toHistory(
  messages: GroupRecord['messages'],
): ConversationMessage[] {
  const out: ConversationMessage[] = [];
  for (const m of messages ?? []) {
    const kind = m.sender_kind ?? 'user';
    if (kind === 'system') continue; // bridge notices aren't model context
    const role = kind === 'agent' ? 'assistant' : 'user';
    const text = typeof m.content === 'string' ? m.content : '';
    if (text) out.push({ role, blocks: [{ kind: 'text', text }] });
  }
  return out;
}

/**
 * Extract clean assistant text from one `text-delta` chunk value.
 *
 * spawner-bridge (CLI/ACP/MCP) forwards each SSE event verbatim as a text-delta
 * whose value is the wire line `event: <name>\ndata: <json>\n\n` — lossless on
 * the wire, but the consumer must re-parse. We pull `data.text` only from
 * `event: text` blocks (NOT `raw`/`usage`/`complete`, which also carry a
 * `text` field). ApiClientCallable (byok) yields clean text already (no
 * `event:` prefix) → passed through unchanged.
 */
function sseWireToText(value: string): string {
  if (!/^event:\s/m.test(value)) return value; // byok clean text
  let out = '';
  for (const block of value.split('\n\n')) {
    let ev = '';
    let data = '';
    for (const line of block.split('\n')) {
      if (line.startsWith('event:')) ev = line.slice(6).trim();
      else if (line.startsWith('data:')) data = line.slice(5).trim();
    }
    if (ev === 'text' && data) {
      try {
        const j = JSON.parse(data) as { text?: unknown };
        if (typeof j.text === 'string') out += j.text;
      } catch {
        /* non-JSON data line — skip */
      }
    }
  }
  return out;
}

/**
 * 2026-11-04 思考剥离（纯函数，可单测）— 从 agent 最终聊天回复里去掉
 * `<sf:thinking>…</sf:thinking>` 思考段。zhipu 思考模型（glm-4.6/5.x）经
 * ApiClientCallable 的 reasoning_content 包装，流式文本里成对/未闭合（max_tokens
 * 截断）两种形态都会出现；思考过程已由过程卡（thinking 卡）实时展示，最终
 * 消息只留正文。与 src/api/llm.ts 人设生成同款策略。
 *
 * 2026-11-05 — 补连字符形态 `<sf-thinking>`：模型模仿 sf: 协议时经常把冒号
 * 写成连字符（群聊气泡实证：`<sf-thinking>The user said…</sf-thinking>` 整段
 * 英文思考漏进中文界面）。冒号/连字符 × 成对/未闭合全部剥干净。
 */
export function stripThinking(s: string): string {
  // <sf:thinking> / <sf-thinking>（属性可选）… </sf:thinking> / </sf-thinking>。
  return s
    .replace(/<sf[:-]thinking(?:\s[^>]*)?>[\s\S]*?<\/sf[:-]thinking>/g, '')
    .replace(/<sf[:-]thinking(?:\s[^>]*)?>[\s\S]*$/g, '');
}

// ── 2026-11-07 流式标签剥离 ──────────────────────────────────────────────
/** 完整标签名（开/闭 × 冒号/连字符），与 stripThinking 双分隔符规则一致。 */
const THINK_TAG_NAMES = ['sf:thinking', 'sf-thinking', '/sf:thinking', '/sf-thinking'];
/** 完整开/闭标签（属性可选）——整体即「定界符」，从流里消失。 */
const THINK_TAG_DELIM_RE = /<\/?sf[:-]thinking(?:\s[^>]*)?>/g;

/**
 * 尾部疑似「被切断的标签开头」→ 返回该后缀起点（最长存活后缀），否则 -1。
 *
 * 存活判定（core = 最后候选 `<` 之后的文本）：
 *   - 裸 `<` / `</` 等名字尚未跑偏的前缀 → 存活（等后续 chunk 补全）；
 *   - 名字段被空白提前终结（`<sf:thi x`）→ 名字必须**完整等于**标签名且
 *     属性段未出现 `>` 才存活，否则字面文本；
 *   - 无空白的名字段是完整标签名的前缀即存活；含 `>` 自然出局。
 * 取**最早**存活的 `<`（最长后缀）——`<sf:thinking x=<sf:thi` 这类属性段里
 * 带 `<` 的形态要整体 hold，不能只 hold 尾巴。
 */
function partialTagStart(rest: string): number {
  for (let i = rest.indexOf('<'); i >= 0; i = rest.indexOf('<', i + 1)) {
    const core = rest.slice(i + 1);
    if (!core) return i; // 裸 '<' 结尾 — 可能是标签第一字节
    if (/\s/.test(core[0])) continue; // `< x` 不可能是标签
    const ws = core.search(/\s/);
    const name = ws < 0 ? core : core.slice(0, ws);
    const alive = ws < 0
      ? THINK_TAG_NAMES.some((n) => n.startsWith(name))
      : THINK_TAG_NAMES.includes(name) && !core.slice(ws).includes('>');
    if (alive) return i;
  }
  return -1;
}

/**
 * 逐 chunk 流式剥 `<sf[:-]thinking>` **定界符**（思考内容保留）——B3 过程卡
 * 把 text-delta 逐片点亮进卡体，模型（zhipu reasoning 包装 / 模型模仿 sf:
 * 协议）会在正文流里写思考标签，原样 append 会让流式卡体「原始标签与正文
 * 混排」（2026-11-07 截图反馈）。
 *
 * 与 stripThinking 的分工：
 *   - stripThinking：**整段**替换，落库前剥最终回复（思考内容整段丢弃，
 *     气泡只留正文）；
 *   - 本状态机：**逐 chunk**，只剥定界符、思考内容保留在卡体——与结构化
 *     thinking-delta 通道（纯思考文本点亮同一张卡）对齐，过程细节不丢。
 *
 * 跨 chunk 边界：标签会被切断在任意字节（`<sf:thin` | `king>…`），疑似
 * 标签前缀 hold 住等后续 chunk 补全再判，绝不闪现半截标签；流结束时
 * flush() 丢弃仍未补全的残段（未完成的开标签不该以碎片形态进卡体）。
 */
export function createThinkingTagStream(): {
  push(piece: string): string;
  flush(): void;
} {
  let pending = '';
  return {
    push(piece: string): string {
      const s = pending + piece;
      pending = '';
      let out = '';
      let last = 0;
      THINK_TAG_DELIM_RE.lastIndex = 0;
      let m: RegExpExecArray | null;
      while ((m = THINK_TAG_DELIM_RE.exec(s)) !== null) {
        out += s.slice(last, m.index);
        last = m.index + m[0].length;
      }
      const rest = s.slice(last);
      const hold = partialTagStart(rest);
      if (hold >= 0) {
        out += rest.slice(0, hold);
        pending = rest.slice(hold);
      } else {
        out += rest;
      }
      return out;
    },
    flush(): void {
      pending = '';
    },
  };
}

/**
 * G1（2026-06-13）— 网关 fanout 把 callable.turn() 吐出的 tool-use/tool-result
 * chunk 投影成 tool_call/tool_echo TimelineMessage，让会话 Timeline 真显示工具
 * 调用（前端 ToolCallChip/ToolEchoLine 渲染器+contracts 早已就位，只缺网关 emit）。
 * 映射与 timeline-projector.onToolUse/onToolResult 一致(args 截 200、空 result 跳过)。
 * gw 为 null（startGatewayRun 失败）时整体 no-op，不影响聊天主链路。
 *
 * 2026-11-06 Agent 检查器 — who 参数（可选）：群聊 fanout 每个 agent 的
 * callAgent 传入自己的 id/名，工具卡带 agent_id/agent_name 归属；单聊/老调用
 * 不传 = 无归属（additive，检查器对无归属卡不筛选）。
 */
export interface ToolOwner {
  agentId: string;
  agentName: string;
}

/** 网关 gw 接口（emitPatch 可选——老调用方/测试可能只给 emitMessage）。 */
type ToolGw = {
  nextId(): string;
  turnId: string;
  emitMessage(m: TimelineMessage): void;
  emitPatch?(p: MessagePatch): void;
} | null;

// gap #2（2026-06-24）— 按 gw 记当前未落定的 tool_call（id + 开始时间），
// 用于 tool-result 时发 tool_finalize（耗时 + 成功/失败 + 结果摘要）。WeakMap
// 随 gw 生命周期自动回收，不污染 gw 类型。
// 2026-11-06 — 单槽改 per-agent 槽（Map<agentId, open>）：并发 DAG 多 agent
// 共享同一 gw，单槽会互相顶替导致 finalize 串台/永久转圈；无 who（单聊）落
// '' 槽，行为与旧单槽完全一致。
const _openToolByGw = new WeakMap<object, Map<string, { id: string; startMs: number }>>();

/** body 看起来像错误？（与 timeline-projector.onToolResult 同启发）。 */
function looksLikeToolError(body: string): boolean {
  return /^\s*(error|exception|traceback|failed|enoent|permission denied)/i.test(body)
    || (/\b(error|failed)\b/i.test(body.slice(0, 80)) && body.length < 200);
}

export function emitToolChunk(gw: ToolGw, chunk: TurnChunk, who?: ToolOwner): void {
  if (!gw) return;
  // per-agent 开放工具槽（'' = 无归属单聊路径，与旧单槽行为一致）。
  const slotKey = who?.agentId ?? '';
  const openMap = _openToolByGw.get(gw) ?? new Map<string, { id: string; startMs: number }>();
  _openToolByGw.set(gw, openMap);
  const attribution = who ? { agent_id: who.agentId, agent_name: who.agentName } : {};
  if (chunk.type === 'tool-use') {
    let argsSummary = '';
    try {
      argsSummary =
        typeof chunk.tool.tool_input === 'string'
          ? chunk.tool.tool_input
          : JSON.stringify(chunk.tool.tool_input ?? {});
    } catch {
      argsSummary = String(chunk.tool.tool_input);
    }
    if (argsSummary.length > 200) argsSummary = argsSummary.slice(0, 200) + '…';
    // 前一个 tool 没收到 result 就被顶替 → 先落定为 ok（防永久转圈）。
    // per-agent 槽：并发 DAG 下别的 agent 的开放工具不受影响。
    const prev = openMap.get(slotKey);
    if (prev && gw.emitPatch) {
      gw.emitPatch({ id: prev.id, op: 'tool_finalize', status: 'ok', duration_ms: Math.max(0, Date.now() - prev.startMs) });
    }
    const id = gw.nextId();
    openMap.set(slotKey, { id, startMs: Date.now() });
    gw.emitMessage({
      id,
      kind: 'tool_call',
      turn_id: gw.turnId,
      ts: Date.now(),
      name: chunk.tool.tool_name,
      args_summary: argsSummary,
      status: 'running',
      ...attribution,
    });
  } else if (chunk.type === 'tool-result') {
    const body = (chunk.result.output ?? '').trim();
    // gap #2 — 落定该 agent 最近未结的 tool_call（耗时 + 成功/失败 + 结果摘要）。
    const open = openMap.get(slotKey);
    if (open && gw.emitPatch) {
      gw.emitPatch({
        id: open.id,
        op: 'tool_finalize',
        status: looksLikeToolError(body) ? 'error' : 'ok',
        duration_ms: Math.max(0, Date.now() - open.startMs),
        result_summary: summarizeToolResult(body),
      });
      openMap.delete(slotKey);
    }
    if (!body) return;
    gw.emitMessage({
      id: gw.nextId(),
      kind: 'tool_echo',
      turn_id: gw.turnId,
      ts: Date.now(),
      body,
      ...attribution,
    });
  }
}

/**
 * Resolve the CLI/ACP/MCP working directory (cwd) for a group.
 *
 * Priority (2026-05-30):
 *   1. group.workspace_dir — user-picked absolute path (group settings DirPicker).
 *      Used verbatim if it's an existing absolute directory. The bypassed CLI
 *      can read/write here, so it's the user's explicit choice.
 *   2. Fallback scratch dir OUTSIDE the repo:
 *      `$SHADOWFLOW_CHAT_DIR | ~/.shadowflow-chat`/chat-workspaces/<groupId>.
 *      Previously this lived under the repo (`process.cwd()/.shadowflow/...`),
 *      which let `claude` follow the git root and read the whole ShadowFlow
 *      codebase — `bypassPermissions + cwd-in-repo` is the dangerous combo we
 *      avoid here (see docs/architecture/chat-cli-cwd-and-permissions.md).
 */
function resolveChatWorkspace(groupId: string, userDir?: string): string {
  if (userDir && userDir.trim() && isAbsolute(userDir.trim())) {
    const p = userDir.trim();
    try {
      if (statSync(p).isDirectory()) return p;
    } catch {
      /* user dir gone / unreadable — fall through to default scratch */
    }
  }
  const root = process.env.SHADOWFLOW_CHAT_DIR?.trim() || join(homedir(), '.shadowflow-chat');
  const dir = join(root, 'chat-workspaces', groupId.replace(/[^\w-]/g, '_'));
  try {
    mkdirSync(dir, { recursive: true });
  } catch {
    /* best-effort; spawn will surface a clearer error if it truly can't run */
  }
  return dir;
}

/** Resolve executor → callable opts (key only for byok:/anthropic-direct). */
function resolveExecutorKey(
  executor: string,
  headers: Request['headers'],
): string | undefined {
  if (executor.startsWith('byok:')) {
    const provider = executor.slice(5);
    if (isProviderId(provider)) return resolveProviderKey(provider, headers);
  }
  if (executor === 'anthropic-direct') return resolveProviderKey('anthropic', headers);
  return undefined; // cli:/acp:/mcp: don't need a key
}

/**
 * 2026-11-04 默认 executor 回退（NeverThrow：任何失败 → 'cli:claude' 现状兜底）。
 * 读取 settings/byok：第一个 enabled 且配了 key 的 provider → `byok:<id>`。
 * 让「设置页配好 zhipu key」这个动作对群聊默认对话生效，而不是让每条消息都
 * 掉进 cli:claude 静默挂起。provider 顺序读 settings 插入序（用户配的第一个
 * provider 优先），无任何可用 BYOK → 'cli:claude'（历史行为零回归）。
 */
export function pickDefaultExecutor(): string {
  try {
    // 惰性 require 与 dispatcher 同款防循环依赖。
    const { getSetting } = require('../../storage/settings') as {
      getSetting: (k: string) => unknown;
    };
    const byok = getSetting('byok') as
      | { providers?: Record<string, { apiKey?: string; enabled?: boolean }> }
      | undefined;
    for (const [id, p] of Object.entries(byok?.providers ?? {})) {
      if (p?.enabled && typeof p.apiKey === 'string' && p.apiKey.trim()) {
        return `byok:${id}`;
      }
    }
  } catch {
    /* settings 不可用 → CLI 兜底 */
  }
  return 'cli:claude';
}

// ── Polynoia 对标 · 富卡片发射助手（经 gateway run 落群时间线） ───────────────

type GwLike = ReturnType<typeof startGatewayRun>;

/** intent 帧 payload（WorkBuddy 式派发决策可见化，2026-08-23）。 */
export interface IntentCardInput {
  /** 用户原始意图（原文，本函数负责截断）。 */
  intent: string;
  target_kind: 'team' | 'agent';
  target_name: string;
  reason: string;
  assignments?: IntentAssignment[];
}

/** intent 帧的意图原文截断长度（卡片只展示概览，全文在时间线里）。 */
const INTENT_TEXT_MAX = 120;

/**
 * 组装 intent 帧 payload（纯函数，可单测）：截断意图原文；拆解明细为空数组
 * 时归一为 undefined（卡片「无明细」与「无拆解」同一视觉，不伪造空列表）。
 */
export function buildIntentCard(input: IntentCardInput): {
  intent: string;
  target_kind: 'team' | 'agent';
  target_name: string;
  reason: string;
  assignments?: IntentAssignment[];
} {
  return {
    intent: input.intent.replace(/\s+/g, ' ').trim().slice(0, INTENT_TEXT_MAX),
    target_kind: input.target_kind,
    target_name: input.target_name,
    reason: input.reason,
    ...(input.assignments && input.assignments.length > 0
      ? { assignments: input.assignments }
      : {}),
  };
}

/**
 * intent 帧发射（NeverRaising）：gw 为 null / emit 抛错都静默——派发决策
 * 可视化是 additive 增强，绝不影响聊天主链路（与 startGatewayRun 失败语义一致）。
 */
export function emitIntentCard(gw: GwLike, input: IntentCardInput): void {
  if (!gw) return;
  try {
    gw.emitMessage({
      id: gw.nextId(),
      kind: 'intent',
      turn_id: gw.turnId,
      ts: Date.now(),
      ...buildIntentCard(input),
    });
  } catch {
    /* NeverRaising */
  }
}

/** commit_record 卡 — agent 提交 / 编排者合并提交共用。
 *  2026-11-07 检查器产出归属 — who 可选：agent 自己的提交带 agent_id/agent_name
 *  （检查器按 agent 筛产出）；编排者合并提交不传 = 无归属（不进单 agent 流）。 */
export function emitCommitCard(gw: ToolGw, c: {
  repo: string; sha: string; short_sha: string; message: string; author: string;
  date?: string; files_changed: number; insertions: number; deletions: number;
  files?: WorktreeCommit['files'];
}, who?: ToolOwner): void {
  if (!gw || !c.sha) return;
  const attribution = who ? { agent_id: who.agentId, agent_name: who.agentName } : {};
  gw.emitMessage({
    id: gw.nextId(),
    kind: 'commit_record',
    turn_id: gw.turnId,
    ts: Date.now(),
    repo: c.repo,
    sha: c.sha,
    short_sha: c.short_sha,
    message: c.message,
    author: c.author,
    files_changed: c.files_changed,
    insertions: c.insertions,
    deletions: c.deletions,
    ...(c.date ? { date: c.date } : {}),
    ...(c.files && c.files.length > 0 ? { files: c.files } : {}),
    ...attribution,
  });
}

/** file_diff 卡（每个变更文件一张，git-introspect 已限量截断）。
 *  2026-11-07 — who 同 emitCommitCard（与 commit_record 成对归属）。 */
export function emitFileDiffCards(gw: ToolGw, diffs: GitFileDiff[], who?: ToolOwner): void {
  if (!gw) return;
  const attribution = who ? { agent_id: who.agentId, agent_name: who.agentName } : {};
  for (const fd of diffs) {
    gw.emitMessage({
      id: gw.nextId(),
      kind: 'file_diff',
      turn_id: gw.turnId,
      ts: Date.now(),
      path: fd.path,
      added: fd.added,
      removed: fd.removed,
      lines: fd.lines,
      ...(fd.language ? { language: fd.language } : {}),
      ...attribution,
    });
  }
}

/** agent 干完即提交 + 证据卡（commit_record + file_diff）。失败静默 — 不影响聊天主链路。 */
async function commitAndEvidence(
  gw: GwLike,
  wt: PreparedWorktree,
  who: ToolOwner,
  taskTitle: string,
): Promise<void> {
  try {
    const commit = await commitWorktree(
      wt.dir,
      `[sf] ${who.agentName}: ${taskTitle.slice(0, 60)}`,
      who.agentName,
    );
    if (!commit?.sha) return;
    emitCommitCard(gw, {
      repo: who.agentName,
      sha: commit.sha,
      short_sha: commit.short_sha,
      message: commit.message,
      author: commit.author,
      date: commit.date,
      files_changed: commit.files_changed,
      insertions: commit.insertions,
      deletions: commit.deletions,
      files: commit.files,
    }, who);
    const ev = await inspectGitRun(wt.dir, wt.baseSha, undefined);
    if (ev) emitFileDiffCards(gw, ev.fileDiffs, who);
  } catch (e) {
    console.warn('[groups-chat] worktree commit/evidence failed (non-fatal):', e);
  }
}

/** MERGE 收尾 — 各 agent 分支并入集成分支，出合并卡/冲突表 + 冲突系统消息。 */
async function integrateAndReport(
  gw: GwLike,
  groupId: string,
  repoRoot: string,
  runKey: string,
  orderedAgents: string[],
  wtByAgent: Map<string, PreparedWorktree>,
): Promise<void> {
  if (wtByAgent.size === 0) return;
  try {
    const branches = orderedAgents
      .map((id) => wtByAgent.get(id)?.branch)
      .filter((b): b is string => !!b);
    const results = await integrateAll(repoRoot, runKey, branches);
    if (!results || results.length === 0) return;
    const rows: (string | number)[][] = [];
    for (const r of results) {
      // 分支名 agent/<agentId>/<runKey> → 反查 agent。
      const agentId = r.branch.split('/')[1] ?? r.branch;
      if (r.ok) {
        emitCommitCard(gw, {
          repo: 'integration',
          sha: r.mergeSha ?? 'unknown',
          short_sha: r.shortSha ?? '',
          message: `merge ${agentId} → ${runKey.split('-')[0]}`,
          author: 'orchestrator',
          files_changed: 0,
          insertions: r.insertions,
          deletions: r.deletions,
        });
        rows.push([agentId, '已合并', r.insertions, r.deletions]);
      } else {
        rows.push([agentId, '冲突 needs-manual', r.conflicts.length, r.conflicts.slice(0, 3).join('、')]);
        await pyPostMessage(groupId, {
          content: `[worktree] ${agentId} 的分支合并冲突（needs-manual）：${r.conflicts.join('、') || '未知文件'}`,
          sender_name: 'system',
          sender_kind: 'system',
        }).catch(() => {});
      }
    }
    if (gw && rows.length > 1) {
      gw.emitMessage({
        id: gw.nextId(),
        kind: 'table_panel',
        turn_id: gw.turnId,
        ts: Date.now(),
        caption: '回合合并结果',
        columns: ['Agent', '结果', '新增', '删除 / 冲突文件'],
        rows,
      });
    }
  } catch (e) {
    console.warn('[groups-chat] worktree integration failed (non-fatal):', e);
  }
}

// ── 寒暄判定（2026-11-07）— 实现已迁入 lib/chat-strategy（策略矩阵第一行，
// 纯函数单测在 chat-strategy.test.ts）。此处兼容再导出：groups-chat-mention
// .test.ts 等既有引用方仍从本模块导入。
export { isCasualChat };

// ── 2026-11-08 图→博文流水线装配 ─────────────────────────────────────────────
// 审批注册/决定解析/取消全部复用本模块的 pendingApprovals 单真源（显式审批
// API 与会话短语两条决定路径对流水线审批门天然生效）；数据面走 be-worker 的
// craft-posts/craft-products REST。门节点用 DAG approve 边的目标 agentId
// （品牌定稿=内容策划师、对外发布=运营专员，roster 顺序见 craft-team-setup），
// 编制缺失时回落合成 id（pendingApprovals 键空间内仍唯一）。
const craftPostPipeline = createCraftPostPipeline({
  registerApproval: (groupId, nodeId, meta) => registerPendingApproval(groupId, nodeId, meta),
  cancelApproval: (groupId, nodeId) => {
    cancelPendingApproval(groupId, nodeId);
  },
  decide: parseApprovalDecision,
  notice: (groupId, content) =>
    pyPostMessage(groupId, { content, sender_name: 'system', sender_kind: 'system' }).catch(
      () => {},
    ),
  api: defaultCraftPostApi(),
  gateNodeIds: () => {
    const ids = readCraftTeamRef()?.agent_ids ?? [];
    return {
      brand: ids[3] ?? 'craft-post:brand',
      publish: ids[5] ?? 'craft-post:publish',
    };
  },
});

/**
 * [build-team]/[dispatch]/[draft] 流程动作执行（2026-11-07 总经理主控）。fail-soft：
 * 单个动作失败落系统消息，不打断聊天主链路。
 *
 *   build-team —— 幂等搭建代卖团队（setupCraftTeam），落系统消息报结果；
 *   dispatch —— 向代卖工作群下发任务（@提及成员，总经理 agent 身份发言 +
 *     显式发起新一轮 fan-out，@提及定向派给被点名的成员）。**只在总经理 DM
 *     里执行**：工作群里派活靠 DAG 交接，群里再落 dispatch 会双重派发（且
 *     可能自我循环）。
 *   draft —— 图→博文流水线草稿（2026-11-08）：落 craft_posts(status:draft)
 *     进入「用户确认→两道审批门→自动发布→落商品」流水线；图片取本轮用户
 *     随行附件（attachments）与标记自带 images 的并集。
 */
async function runCraftFlowActions(
  srcGroup: GroupRecord,
  actions: CraftAction[],
  ctx: { executor: string; model: string | undefined; headers: Request['headers'] },
  attachments?: UserAttachment[],
  draftTurn = false,
): Promise<void> {
  const notice = (content: string) =>
    pyPostMessage(srcGroup.group_id, {
      content,
      sender_name: 'system',
      sender_kind: 'system',
    }).catch(() => {});
  // 图→博文流水线草稿：同轮多条 [draft] 取最后一条（模型返工后最新版为准）。
  let draftAction: Extract<CraftAction, { kind: 'draft' }> | null = null;
  for (const a of actions) {
    if (a.kind === 'build-team') {
      try {
        const r = await setupCraftTeam();
        await notice(
          `[team] 代卖团队已就绪（${r.agent_names.join('、')}）${r.created ? '（新建）' : '（复用）'}`,
        );
      } catch (e) {
        await notice(`[team] 建团队失败：${(e as Error).message}`);
      }
    } else if (a.kind === 'draft') {
      draftAction = a;
    } else if (a.kind === 'dispatch') {
      if (srcGroup.kind !== 'dm') continue; // 群里派活走 DAG 交接，不重复下发
      const target = readCraftTeamRef()?.group_id;
      if (!target) {
        await notice('[dispatch] 还没有代卖工作群，先让我建团队（[build-team]）再派活。');
        continue;
      }
      const content = `${a.to.map((n) => `@${n}`).join(' ')} ${a.text}`;
      try {
        // 2026-11-07 修复「总经理应该直接回复消息，头像应该保持」：派活消息
        // 归属总经理本人（sender_kind='agent' + agent_id）——聊天流实时渲染为
        // 带头像的总经理直接消息（此前 sender_kind='user'：不 publish（用户
        // 消息防乐观渲染重复的规则把它误伤）→ 实时看不到，回放又被渲染成无
        // 头像的用户气泡）。agent 消息不会触发任何自动应答桥（Python/Node 都
        // 只对 user 消息应答），fan-out 仍由我们显式发起（@提及定向派给被
        // 点名的成员）。模型语义：总经理派活在 history 里是 assistant 轮，
        // 与群里其他 agent 发言一致；派活指令由工单 prompt 自包含承载。
        const bossId = srcGroup.agent_ids?.[0];
        await pyPostMessage(
          target,
          {
            content,
            sender_name: '总经理',
            sender_kind: 'agent',
            ...(bossId ? { agent_id: bossId } : {}),
          },
          { noDispatch: true },
        );
        void runFanout(target, ctx.executor, ctx.model, ctx.headers, content).catch(() => {});
      } catch (e) {
        await notice(`[dispatch] 派活失败：${(e as Error).message}`);
      }
    }
  }
  // 图→博文流水线：草稿落 craft_posts(draft) + 进入「确认→两道审批门→自动
  // 发布→落商品」（编排器内部 fail-soft 播报，不打断聊天主链路）。
  if (draftAction) {
    await craftPostPipeline.handleDraft(srcGroup.group_id, draftAction, attachments).catch(() => {});
  } else if (draftTurn) {
    // 2026-11-08 协议行 fail-soft — 草拟回合没解析到 [draft] 标记（模型模仿了
    // 历史展示格式/漏吐协议行）：必须可见报出来，不许静默无落库让用户干等。
    await notice(
      '⚠️ 本轮草拟未解析到 [draft] 协议标记，草稿未落库、未进入确认环节（模型输出缺结构化协议行）。可直接重发「根据这张图发小红书博文草稿」重试。',
    );
  }
}

/**
 * Background fan-out: generate + persist one reply per group agent.
 * Never throws to the caller (errors become sender_kind='system' notices).
 * @param latestUserText 最新用户消息原文（mention 解析用；调用方从持久化记录
 *   取，缺省时 runFanout 自行从 group.messages 反查——测试/旧调用方兼容）。
 * @param attachments 2026-11-07 拖拽传图 — 本条用户消息的随行附件；派发时以
 *   goalWithAttachments 引用块注入 agent 上下文（绝对路径供 read_file/读图）。
 */
async function runFanout(
  groupId: string,
  executor: string,
  model: string | undefined,
  headers: Request['headers'],
  latestUserText?: string,
  knowledgePackIds?: string[],
  attachments?: UserAttachment[],
): Promise<void> {
  const apiKey = resolveExecutorKey(executor, headers);

  const group = await pyGet<GroupRecord>(`/api/groups/${encodeURIComponent(groupId)}`);
  if (!group) return;
  // CLI/ACP/MCP need a cwd; byok/anthropic-direct ignore it. Honor the group's
  // user-picked workspace_dir, else a repo-external scratch dir.
  const workspace = resolveChatWorkspace(groupId, group.workspace_dir);
  const allAgentIds = (group.agent_ids ?? []).slice(0, MAX_FANOUT_AGENTS);
  if (allAgentIds.length === 0) {
    await pyPostMessage(groupId, {
      content: '[chat] No agents are members of this group.',
      sender_name: 'system',
      sender_kind: 'system',
    }).catch(() => {});
    return;
  }

  // ── @ 提及定向派活（OpenBot 语义）────────────────────────────────────────
  // 提取消息中的 @token 并对照成员名单解析；命中 ≥1 个成员 → 只派活给被点名者。
  const userText =
    typeof latestUserText === 'string' && latestUserText.trim()
      ? latestUserText
      : ([...(group.messages ?? [])]
          .reverse()
          .find((m) => (m.sender_kind ?? 'user') === 'user')?.content ?? '');
  const rosterCandidates: MentionCandidate[] = [];
  const planRoster: StrategyAgent[] = [];
  for (const id of allAgentIds) {
    try {
      const a = await pyGet<AgentRecord>(`/api/agents/${encodeURIComponent(id)}`);
      rosterCandidates.push({ id, name: a?.name || id });
      planRoster.push({ id, name: a?.name || id, soul: a?.soul ?? '' });
    } catch {
      rosterCandidates.push({ id, name: id });
      planRoster.push({ id, name: id, soul: '' });
    }
  }
  const { mentionedIds, cleanText } = parseMentions(userText, rosterCandidates);
  const mentioned = new Set(mentionedIds);
  // @ 未命中可见提示（零 LLM）：消息里有 @token 但一个都没对上成员 → 用户
  // 以为在点名、系统却全员派发，这是演示里最容易被问「为什么 @ 没生效」的
  // 场景。落一条 system 提示（可解释性 > 沉默降级）。纯文本无 @ → 不打扰。
  const hasAtToken = /(^|[\s，。！？、：；）】」』》〉【「『,.!?;:)\]])@[^\s]/u.test(userText);
  if (!mentioned.size && hasAtToken) {
    const names = rosterCandidates.map((c) => `@${c.name}`).join('、');
    await pyPostMessage(groupId, {
      content: `[mention] 消息里的 @ 没有匹配到任何群成员，已按常规流程派发给全体成员。可点名的成员：${names}`,
      sender_name: 'system',
      sender_kind: 'system',
    }).catch(() => {});
  }

  // ── 意图识别 + 策略矩阵（2026-11-07，GrokBot 群聊范式）──────────────────
  // 用户消息 → 意图（寒暄/问答/讨论/任务）→ 策略矩阵定协作策略（单人应答/
  // 专家应答/流水线/并行拆分/圆桌/全员）→ 工单拆解（LLM 编排者优先，启发式
  // 兜底）——**任何路径都不再「原文分发给全体成员」**。@ 点名 = 用户亲自调度
  // （GrokBot「单点 @ 串行交接」语义），定向派活跳过拆解。
  const parseProvider = executor.startsWith('byok:')
    ? executor.slice(5)
    : executor === 'anthropic-direct'
      ? 'anthropic'
      : null;
  // 2026-11-08 图→博文流水线 — craftScoped 判定上移：草拟路由（isPostDraftRequest）
  // 与视觉注入都要在 plan/派发前知道「本轮是代卖域」。
  const craftScoped = isCraftGroup(group);
  let plan: ChatPlan | null = null;
  if (mentioned.size > 0) {
    plan = mentionPlan(userText, cleanText, planRoster, [...mentioned]);
  } else if (craftScoped && isPostDraftRequest(userText)) {
    // 2026-11-08 图→博文流水线 — 草拟请求定向派给内容策划师（结构化 [draft]
    // 输出，工单自包含「只草拟不发布」纪律）。内容策划师不在编制（团队没建/
    // 改名）→ plan 留空走后续兜底，不硬造路由。手搓 plan（ChatPlan 纯数据，
    // source 用 'mention' 语义：单点定向派活，不进 LLM 拆解）。
    const contentAgent = planRoster.find((a) => a.name === '内容策划师');
    if (contentAgent) {
      plan = {
        intent: 'task',
        strategy: 'solo',
        source: 'mention',
        tasks: [
          { agentId: contentAgent.id, title: '图→博文草拟', prompt: buildDraftPrompt(userText) },
        ],
      };
    }
  } else if (isCasualChat(userText)) {
    plan = casualPlan(userText, planRoster);
  } else if (hasAtToken) {
    // @ 全未命中（上方已发提示）→ 全员参与（既有「按常规流程派发」语义）。
    plan = allHandsPlan(userText, planRoster);
  } else if (parseProvider && apiKey && isProviderId(parseProvider) && userText.trim()) {
    plan = await planWithLlm({
      userText,
      agents: planRoster,
      provider: parseProvider,
      apiKey,
      model,
    });
  }
  if (!plan) plan = heuristicPlan(userText, planRoster);
  const casual = plan.intent === 'casual';
  const planTaskByAgent = new Map<string, ParsedTask>(plan.tasks.map((t) => [t.agentId, t]));
  const agentIds = [...new Set(plan.tasks.map((t) => t.agentId))];
  if (agentIds.length === 0) agentIds.push(allAgentIds[0]); // 防御：至少一人应答
  const planNameOf = (id: string): string => planRoster.find((a) => a.id === id)?.name ?? id;

  // B3 · 网关过程事件 — 本轮 fan-out 开一条 gateway run（互链 conversation 下），
  // 执行期过程经 run 管线 emit；B2 GET /:id/timeline 自动归并回放。
  // startGatewayRun 失败返回 null（聊天主链路照常），所有 gw 操作 `gw?.` 防御。
  const gw = startGatewayRun(groupId, userText);

  // 知识库参考（2026-11-06 对话框知识库接线）— 本轮用户消息检索记忆库命中
  // （fail-soft：Python 未起/超时/零命中 → 空串）；DAG/串行两条派发路径共用。
  // 2026-11-07 手工艺品代卖 — 代卖团队群（isCraftGroup）里用户发来的产品
  // 资料（介绍/图片/文档文本）自动同步到「手工艺品资料」记忆库 pack，并把
  // pack id 并入本轮检索（同步失败不阻塞聊天）。craftScoped 判定见 runFanout
  // 顶部（2026-11-08 图→博文流水线上移复用）。
  let kbPackIds = knowledgePackIds ?? [];
  if (craftScoped) {
    // 文字介绍 → 知识库；随行附件（图片/产品文档）→ 知识库 /files（2026-11-08）。
    // 两路都跑（附件为空时 ingestProductAttachments 直接 null），取任一成功者。
    const packIdText = await ingestProductMaterial(userText).catch(() => null);
    const packIdFiles = await ingestProductAttachments(attachments).catch(() => null);
    const packId = packIdText ?? packIdFiles;
    if (packId && !kbPackIds.includes(packId)) kbPackIds = [...kbPackIds, packId];
  }
  const kbText = await knowledgeBlock(kbPackIds, userText);
  if (kbText) {
    console.log(
      `[groups-chat] injecting knowledge_block (chars=${kbText.length}, packs=${knowledgePackIds?.length ?? 0})`,
    );
  }

  // 2026-11-08 视觉注入（修草拟"盲写"根因）— is_image 附件真实字节读一次，
  // DAG/串行两条派发路径共用：随 turn 的 images 进模型消息（openai-compat
  // image_url data URI / Anthropic image.source），此前模型只收到路径文本、
  // 根本看不到图 → 草稿编造画面。>4MB/超 9 张/读失败的进 skipped 注记
  // （prompt 硬规则要求模型声明「无法读取图片内容」而非虚构）。
  const vision = await readAttachmentImages(attachments).catch(() => ({
    parts: [],
    skipped: [] as string[],
  }));
  const visionNote = skippedImagesNote(vision.skipped);

  try {
    // 2026-06-03 Phase 2a — group 绑了 team 且能读到单一真源 DAG → 按拓扑调度多 agent。
    // 读不到 team(无 team_id / 文件缺失 / 无成员)→ 落到下面的串行 fan-out 降级。
    // 2026-11-07 寒暄路由 — casual 消息不进 DAG（单人接话），同样落到串行路径。
    // ⚠ Phase 2b 剩余(本轮已落:并发上限/外部取消/节点超时/重试):B2 中断恢复(run 状态落盘+重启续跑)、
    //   B3 完整插话续跑(本轮只做"新消息→取消上一轮"最小语义)仍待后续。
    if (!casual && shouldRunTeamDag(group)) {
      const { team } = loadTeamForRun(group.team_id!);
      if (team && team.members.length > 0) {
        // ── 指派集合 → 团队子图收缩（@ 提及同款诱导子图：成员/边双裁剪，
        // conditional 返工边保留）。策略矩阵/点名/拆解只指派子集时，未被
        // 指派的成员不进执行图（不再「原文全员广播」）；全员策略或指派覆盖
        // 全体 → 整图；指派全不在 team 名单（如 @ 的是非团队成员）→ 当没
        // 提过（回落整图 + 原文，既有语义）。
        const fullRoster = team;
        const assignedInTeam = fullRoster.members.filter((id) => planTaskByAgent.has(id));
        const routedToSubset =
          plan.strategy !== 'all-hands' &&
          assignedInTeam.length > 0 &&
          assignedInTeam.length < fullRoster.members.length;
        const effTeam = routedToSubset
          ? restrictTeamToMentions(fullRoster, assignedInTeam)
          : fullRoster;

        // group 已在 runFanout 顶部加载(含 messages);DAG 用单次快照即可(上游上下文经 upstream 参数流转,不靠 history)。
        const history0 = toHistory(group.messages);
        const latestUser0 = [...history0].reverse().find((m) => m.role === 'user');
        // 点名路由时用清洗文本（去掉 @token）当派发 prompt，Agent 不被 @噪音干扰。
        const userPrompt =
          (plan.source === 'mention' ? cleanText : '')
            || latestUser0?.blocks.map((b) => (b.kind === 'text' ? b.text : '')).join('')
            || '';

        // ── 拆解已上移到 runFanout 顶部（plan：点名/寒暄/群呼/LLM/启发式）──
        // 此处只解析 effTeam roster 供卡片名解析。
        const rosterEntries = await Promise.all(
          effTeam.members.map(async (id) => {
            const a = await pyGet<AgentRecord>(`/api/agents/${encodeURIComponent(id)}`).catch(() => null);
            return a ? { id, name: a.name || id, soul: a.soul ?? '' } : null;
          }),
        );
        const roster = rosterEntries.filter((r): r is { id: string; name: string; soul: string } => r !== null);
        const rosterName = (id: string): string => roster.find((r) => r.id === id)?.name ?? id;

        // ── DISPATCH 决策可见化：intent 帧（NeverRaising）───────────────────
        // 用户说一句话后能立刻看到「派给了谁、为什么」：意图 · 策略 · 参与者
        // （点名 / 编排者拆解 / 策略矩阵来源统一经 describePlan 解释）。卡片
        // 本体由前端 NeoGroupChat 的 NeoDispatchCard 渲染（后台折叠行内）。
        emitIntentCard(gw, {
          intent: userPrompt,
          target_kind: 'team',
          target_name: team.name ?? group.team_id!,
          reason: describePlan(plan, rosterName),
          assignments: plan.tasks.map((t) => ({
            agent_id: t.agentId,
            name: rosterName(t.agentId),
            title: t.title,
          })),
        });

        // ── DISPATCH 可视化：plan_card（层号 = 并行批次）───────────────────
        const { layers } = computeDagLayers(effTeam.members, effTeam.edges);
        let planCardId: string | null = null;
        if (gw && team.members.length >= 2) {
          const planTasks: PlanTaskRow[] = [];
          layers.forEach((layer, li) => {
            for (const id of layer) {
              planTasks.push({
                id: `node:${id}`,
                title: planTaskByAgent.get(id)?.title ?? rosterName(id),
                assignee: rosterName(id),
                // U0 绑角色 — 行归属 agent_id 真源（检查器按行筛「含它的任务行」；
                // 老数据回落行 id `node:<agentId>` 同样可判归属）。
                agent_id: id,
                status: 'pending',
                batch: li + 1,
              });
            }
          });
          if (planTasks.length >= 2) {
            planCardId = gw.nextId();
            gw.emitMessage({
              id: planCardId,
              kind: 'plan_card',
              turn_id: gw.turnId,
              ts: Date.now(),
              title:
                plan.tasks.length > 1
                  ? `编排计划 · ${STRATEGY_LABELS[plan.strategy]}`
                  : '编排计划',
              ...(userPrompt ? { goal: userPrompt } : {}),
              tasks: planTasks,
            });
          }
        }
        const planTaskUpdate = (agentId: string, patch: Partial<PlanTaskRow>): void => {
          if (gw && planCardId) {
            gw.emitPatch({ id: planCardId, op: 'plan_update_task', task_id: `node:${agentId}`, patch });
          }
        };

        // ── Polynoia worktree 隔离 ─────────────────────────────────────────
        // 仅当群 workspace 是 git 仓库时启用（每 agent 一分支一 worktree，回合
        // 起始重置）；scratch 共享目录 / 非 git → 行为与现状一致。
        const runKey = `${groupId}-${Date.now()}`;
        const wtByAgent = new Map<string, PreparedWorktree>();
        if (await isGitWorkable(workspace)) {
          for (const id of effTeam.members) {
            const wt = await prepareWorktree(workspace, runKey, id).catch(() => null);
            if (wt) wtByAgent.set(id, wt);
          }
        }

        // ── 交接记录（2026-11-05，OpenBot hop 模型）───────────────────────
        // 本回合一个 turn_seq；SQLite 落库失败时降级为无记录路径（聊天主链路零影响）。
        let turnSeq = 0;
        let hopStore: HopRecorder | null = null;
        // 2026-11-05 Task#10 — hop 生命周期实时播报（hop_card 帧 + hop_update patch）：
        // SQLite 侧照旧落库，播报属 best-effort（gw 为 null / emit 抛错都不影响主链路）。
        // 2026-11-07 播报收口进 chat-dag/hop-broadcast.ts（可直测）：start→running
        // 「交接中」中间态上屏、帧先于补丁（名字解析期间 patch 入队按序 flush）、
        // 按 hopId 索引防 conditional rework 同边多 hop 串卡。
        const agentNameById = new Map<string, string>();
        const resolveAgentName = async (agentId: string): Promise<string> => {
          const hit = agentNameById.get(agentId);
          if (hit) return hit;
          const a = await pyGet<AgentRecord>(`/api/agents/${encodeURIComponent(agentId)}`).catch(() => null);
          const name = a?.name || agentId;
          agentNameById.set(agentId, name);
          return name;
        };
        try {
          turnSeq = nextChatTurnSeq(groupId);
          const dbStore: HopRecorder = {
            open: (edge) => openHop({ group_id: groupId, turn_seq: turnSeq, from_agent: edge.from, to_agent: edge.to }),
            start: (id) => { try { startHop(id); } catch { /* best-effort */ } },
            settle: (id, status, opts) => { try { settleHop(id, status, opts); } catch { /* best-effort */ } },
          };
          const gwRun = gw;
          hopStore = gwRun
            ? createHopBroadcaster(dbStore, {
                nextId: () => gwRun.nextId(),
                turnId: gwRun.turnId,
                emitMessage: (m) => gwRun.emitMessage(m),
                emitPatch: (p) => gwRun.emitPatch(p),
                resolveName: resolveAgentName,
              })
            : dbStore;
        } catch { hopStore = null; }

        // 记忆交接沉淀（2026-11-05）— 本轮实际发言 agent 收集器（执行序），
        // 回合结束后 sinkRoundHandoff 落交接包（零 LLM、autoLearn 开关）。
        const roundSpeakers: Array<{ id: string; name: string; excerpt: string }> = [];

        const deps: RunTeamDagDeps = {
          getAgent: async (agentId) => {
            const a = await pyGet<AgentRecord>(`/api/agents/${encodeURIComponent(agentId)}`);
            return a ? { name: a.name || agentId, soul: a.soul ?? '' } : null;
          },
          callAgent: async ({ agentId, name, soul, upstream, signal }) => {
            // 用 agentId/name/soul/upstream/signal:agent 回复由 runTeamDagFanout 经独立 postMessage
            // 落库（聊天消息路径零变化）;name 仅用于 B3 过程卡 label。
            // signal 来自 runNodeWithPolicy 的 per-attempt 控制器(超时/外部取消即 fire)→ 取消在飞 turn。
            const upstreamText = upstream.length
              ? `\n\n=== 上游 agent 产出 ===\n${upstream.map((u) => `[${u.from}]\n${u.text}`).join('\n\n')}`
              : '';
            // 意图路由工单 prompt 优先（策略矩阵/点名/编排者拆解给该 agent 的
            // 自包含指令）；未分配（指派全不在 team 名单的整图回落）→ 用户原文。
            const task = planTaskByAgent.get(agentId);
            const basePrompt = task ? task.prompt : userPrompt;
            // Whole-thread 回放保真（2026-11-07）— 与串行路径同款 buildTurnThread，
            // 取代 history0.slice(0,-1) 盲删末位（末位非用户消息时会随机丢段）。
            // prompt 是派生子任务时，被提升用户轮视为被替换（意图拆解语义不变）。
            const { history: turnHistory, prompt: turnPrompt } = buildTurnThread(history0, basePrompt);
            // worktree 隔离 — 本轮该 agent 的专属工作目录。
            const wt = wtByAgent.get(agentId);
            // plan_card 任务行 → running。
            planTaskUpdate(agentId, { status: 'running' });
            // B3 — DAG 节点粒度过程卡（重试时每个 attempt 一张新卡，可见即真实）。
            const thinkingId = gw?.nextId();
            const startedAt = Date.now();
            if (gw && thinkingId) {
              gw.emitMessage({
                id: thinkingId,
                kind: 'thinking',
                turn_id: gw.turnId,
                ts: startedAt,
                label: `${name} 正在思考`,
                status: 'streaming',
                agent_id: agentId,
                agent_name: name,
              });
            }
            let buf = '';
            // 2026-11-08 快速收尾 — 思考体累积（text-delta 剥定界符后的卡体文本 +
            // thinking-delta 结构化思考）：模型把报告全写进 reasoning_content
            //（MiMo 实测）时 stripThinking(buf) 为空，收口以思考体兜底当回复，
            // 杜绝「只有思考卡、没有回复气泡」。
            let thinkingBody = '';
            let errMsg = '';
            // 2026-11-07 流式标签剥离 — 卡体 append 前剥 <sf[:-]thinking> 定界符。
            const thinkStream = createThinkingTagStream();
            try {
              const callable = resolveCallable(executor, { apiKey, model, workspace: wt?.dir ?? workspace });
              for await (const chunk of callable.turn({
                // 2026-11-07 记忆闭环 — soul 后附该 agent 可召回的过往经验。
                system: soul + chatLessonsBlock(agentId),
                // 2026-11-07 拖拽传图 — 附件引用块并入派发上下文（DAG 路径）；
                // 2026-11-08 视觉注入 — is_image 附件真实字节随消息进模型
                //（images → image 块 → openai-compat image_url data URI）。
                prompt:
                  goalWithAttachments(turnPrompt + kbText + upstreamText, attachments) + visionNote,
                history: turnHistory,
                images: vision.parts,
                signal,
                model,
              })) {
                if (chunk.type === 'text-delta') {
                  const piece = sseWireToText(chunk.value);
                  buf += piece;
                  // B3 — 流式片段就地点亮（现有解析粒度 = event:text 的干净文本）。
                  // 2026-11-08 — thinkStream 推进不再依赖 gw（思考体累积给回复
                  // 兜底用），emitPatch 仍 gw 防御。
                  if (piece) {
                    const shown = thinkStream.push(piece);
                    if (shown) {
                      thinkingBody += shown;
                      if (gw && thinkingId) {
                        gw.emitPatch({ id: thinkingId, op: 'thinking_append_body', chunk: shown });
                      }
                    }
                  }
                } else if (chunk.type === 'thinking-delta') {
                  // 2026-11-04 — API 路结构化思考通道：只点亮过程卡，不进 buf。
                  // 2026-11-08 — 同时进思考体累积（回复兜底素材）。
                  if (chunk.value) {
                    thinkingBody += chunk.value;
                    if (gw && thinkingId) {
                      gw.emitPatch({ id: thinkingId, op: 'thinking_append_body', chunk: chunk.value });
                    }
                  }
                } else if (chunk.type === 'tool-use' || chunk.type === 'tool-result') {
                  // G1 — 工具调用/结果就地点亮（tool_call/tool_echo 卡）；
                  // 2026-11-06 检查器 — 带 agent 归属（按 agent 筛后台活动）。
                  emitToolChunk(gw, chunk, { agentId: agentId, agentName: name });
                } else if (chunk.type === 'error') {
                  errMsg = chunk.error?.message ?? 'stream error';
                  break;
                }
              }
            } catch (e) {
              errMsg = e instanceof Error ? e.message : String(e);
            }
            if (gw && thinkingId) {
              // 流收口：未补全的疑似标签残段丢弃，不以碎片形态进卡体。
              thinkStream.flush();
              const elapsed = Date.now() - startedAt;
              gw.emitPatch({ id: thinkingId, op: 'thinking_finalize', duration_ms: elapsed });
              if (errMsg) {
                gw.emitMessage({
                  id: gw.nextId(),
                  kind: 'raw',
                  turn_id: gw.turnId,
                  ts: Date.now(),
                  body: `[chat] ${name} 出错：${humanizeModelError(errMsg)}`,
                  source: 'chat-gateway',
                });
              }
              gw.emitMessage({
                id: gw.nextId(),
                kind: 'msg_foot',
                turn_id: gw.turnId,
                ts: Date.now(),
                status: 'done',
                elapsed_ms: elapsed,
              });
            }
            // plan_card 任务行落终态。
            planTaskUpdate(agentId, errMsg
              ? { status: 'failed' }
              : { status: 'done', elapsed_ms: Date.now() - startedAt });
            // Polynoia MERGE 前半 — 干完即提交 worktree 产物 + 证据卡
            // （commit_record / file_diff）；无 worktree 或干净树 → 静默跳过。
            if (!errMsg && wt) {
              await commitAndEvidence(gw, wt, { agentId: agentId, agentName: name }, task?.title ?? userPrompt);
            }
            // 2026-11-04 思考剥离 — 与串行路径同款：<sf:thinking> 段不进最终回复。
            // 2026-11-07 代卖协议标记 — 成功回复里的 [intake]/[order]/[ship] 等
            // 标记落产品盈利看板并从聊天文本剥掉（非代卖群 no-op）；[build-team]/
            // [dispatch] 流程动作在挂钩点执行（总经理主控）。
            // 2026-11-08 图→博文流水线 — 草拟回合防线：[post] 降级 [draft]
            //（soul 的「产出可发布贴文输出 [post]」不能把未确认草稿直接发出去），
            // [draft] 走 runCraftFlowActions 挂钩点落流水线。
            // 2026-11-08 快速收尾 — 回复兜底（根因 A）：模型（MiMo）把报告全写进
            // reasoning_content 时剥思考后正文为空 → 取思考体当回复，杜绝
            // 「只有思考卡、没有回复气泡」。正文优先，思考体次之。
            const replySource = stripThinking(buf).trim() || thinkingBody.trim();
            if (errMsg) return { text: replySource, error: errMsg };
            const draftTurn = craftScoped && isPostDraftRequest(basePrompt);
            const dagText = draftTurn ? convertPostMarkersToDraft(replySource) : replySource;
            const appliedDag = await applyCraftMarkers(dagText, { scoped: craftScoped });
            await runCraftFlowActions(group, appliedDag.actions, { executor, model, headers }, attachments, draftTurn);
            return { text: appliedDag.cleaned, error: undefined };
          },
          postMessage: async (m) => {
            await pyPostMessage(groupId, {
              content: m.content,
              sender_name: m.sender_name,
              sender_kind: m.sender_kind,
              // U0 绑角色 — 透传 agent 回话的发送者 agent_id（system 消息无）。
              ...(m.agent_id ? { agent_id: m.agent_id } : {}),
            }).catch(() => {});
            // 记忆交接沉淀（2026-11-05）— 收集本轮实际发言的 agent（执行序）。
            if (m.sender_kind === 'agent' && m.agent_id) {
              roundSpeakers.push({
                id: m.agent_id,
                name: m.sender_name,
                excerpt: m.content.replace(/\s+/g, ' ').trim().slice(0, 160),
              });
            }
          },
          // 交接记录（2026-11-05）— hopStore 为 null（SQLite 异常）时省略，执行器走无记录路径。
          ...(hopStore ? { hops: hopStore } : {}),
          // ── approve 边人工审批门（2026-11-05，OpenBot 审批纪律）────────────
          // 执行器遇带 approve 入边的节点 → 挂起 pendingApprovals 等用户决定；
          // 批准放行 / 拒绝标 blocked。无 approve 边的团队零开销。
          ...(effTeam.edges.some((e) => e.kind === 'approve')
            ? {
                approval: {
                  request: ({ nodeId, nodeName, preview }: { nodeId: string; nodeName: string; preview: string; signal: AbortSignal }) =>
                    registerPendingApproval(groupId, nodeId, { nodeName, preview }).then((v) => {
                      // 决定落一条系统消息（审批留痕；postMessage 失败不回传）。
                      void pyPostMessage(groupId, {
                        content: `[approval] ${nodeName} 的审批结果：${v === 'approved' ? '已批准 ✅' : '已拒绝 ❌'}`,
                        sender_name: 'system',
                        sender_kind: 'system',
                      }).catch(() => {});
                      return v;
                    }),
                },
                onNodeBlocked: (blockedId: string) => {
                  // plan_card 任务行 → blocked（OpenBot work_items 语义：审批拒 = 不再等）。
                  planTaskUpdate(blockedId, { status: 'blocked' });
                },
              }
            : {}),
        };
        let dagController: AbortController | undefined;
        try {
          dagController = swapDagRun(groupId, activeDagRuns);
          await runTeamDagFanout(effTeam, deps, userPrompt, {
            signal: dagController.signal,
            maxConcurrency: MAX_FANOUT_AGENTS,
            // nodeTimeoutMs/defaultMaxRetries 用 runTeamDagFanout 默认值(120s / 1)。
          });
        } finally {
          // 仅当注册表里仍是本 controller 时才删(避免误删后来者)。
          if (dagController && activeDagRuns.get(groupId) === dagController) activeDagRuns.delete(groupId);
        }
        // 交接摘要（零 LLM，从 hops 表现算）— 对齐「记忆交接」体验：本回合谁把
        // 什么交给了谁、哪里断了他能接住。postMessage 失败静默（best-effort）。
        if (hopStore) {
          try {
            const summary = summarizeHops(groupId, turnSeq);
            if (summary) {
              await pyPostMessage(groupId, {
                content: summary,
                sender_name: 'system',
                sender_kind: 'system',
              });
            }
          } catch { /* best-effort */ }
        }
        // 记忆交接沉淀（2026-11-05 GrokBot 对齐）— 回合结论落 memory_handoffs
        // 交接包（最后发言 → 首位执行者），下游 agent accept 后能接班。静默。
        sinkRoundHandoff({ groupId, turnSeq, goal: userPrompt, speakers: roundSpeakers });
        // ── Polynoia AGGREGATE/MERGE 收尾 ─────────────────────────────────
        // 各 agent 分支按 DAG 层序并入集成分支 sf/run/<runKey>（专用 integration
        // worktree，不碰用户检出分支）；合并卡 / 冲突表 + 冲突系统消息。
        // 用户插话取消的回合不合并（半成品分支留给 needs-manual）。
        if (!dagController?.signal.aborted) {
          await integrateAndReport(
            gw,
            groupId,
            workspace,
            runKey,
            layers.flat(),
            wtByAgent,
          );
        }
        // 用户插话取消上一轮 → 'canceled'；否则本轮过程完整 → 'succeeded'。
        gw?.finish(dagController?.signal.aborted ? 'canceled' : 'succeeded');
        return;
      }
    }

    // ── 串行降级路径的 worktree 隔离（无 team_id 时）──────────────────────
    // 每 agent 一个 worktree（git 仓库 workspace 时）；无 plan_card（单人无拆解）。
    const serialRunKey = `${groupId}-serial-${Date.now()}`;
    const serialWt = new Map<string, PreparedWorktree>();
    // 记忆交接沉淀收集器（2026-11-05）— 串行路径实际发言 agent（执行序）。
    const serialSpeakers: Array<{ id: string; name: string; excerpt: string }> = [];
    // 本轮派发 prompt（@ 清洗文本或用户原文最后一条；沉淀 summary 用）。
    let serialPrompt = '';
    if (await isGitWorkable(workspace)) {
      for (const id of agentIds) {
        const wt = await prepareWorktree(workspace, serialRunKey, id).catch(() => null);
        if (wt) serialWt.set(id, wt);
      }
    }

    for (const agentId of agentIds) {
      // Reload each round so later agents see earlier replies (fan-out semantics).
      const fresh = await pyGet<GroupRecord>(`/api/groups/${encodeURIComponent(groupId)}`);
      const history = toHistory(fresh?.messages);
      const latestUser = [...history].reverse().find((m) => m.role === 'user');
      // 意图路由工单 prompt 优先（策略矩阵/点名/拆解给该 agent 的自包含指令）；
      // 兜底：点名清洗文本（@token 已删）→ 会话里的用户原文。
      const prompt =
        planTaskByAgent.get(agentId)?.prompt
          || (plan.source === 'mention' ? cleanText : '')
          || latestUser?.blocks.map((b) => (b.kind === 'text' ? b.text : '')).join('')
          || '';
      if (prompt) serialPrompt = prompt;
      // Whole-thread 回放保真（2026-11-07）— 提升用户轮 + 折叠相邻同角色，
      // 取代 history.slice(0,-1) 盲删末位：串行 fan-out 第 2+ 轮末位是上一个
      // agent 的回复，旧删法把它整条删掉（后发言者看不到先发言者），用户消息
      // 反而与 prompt 重复。契约/测试见 lib/turn-thread.ts。
      const { history: turnHistory, prompt: turnPrompt } = buildTurnThread(history, prompt);

      const agent = await pyGet<AgentRecord>(`/api/agents/${encodeURIComponent(agentId)}`);
      if (!agent) {
        await pyPostMessage(groupId, {
          content: `[chat] Agent '${agentId}' not found.`,
          sender_name: 'system',
          sender_kind: 'system',
        }).catch(() => {});
        continue;
      }
      const agentName = agent.name || agentId;
      const soul = agent.soul ?? '';

      // intent 帧（NeverRaising）— 串行降级路径的派发决策：未绑团队 → 按成员
      // 逐个派发。仅多成员群展示派发卡（对群聊有「谁在处理」信息量）；
      // DM/单员工群 1:1 对话无派发语义，跳过（2026-10-31 用户反馈：单聊页
      // 不应出现「群未绑定团队」群聊文案）。
      if (group.kind !== 'dm' && agentIds.length > 1) {
        emitIntentCard(gw, {
          intent: prompt,
          target_kind: 'agent',
          target_name: agentName,
          reason: `${describePlan(plan, planNameOf)}${
            plan.tasks.length > 1 && planTaskByAgent.has(agentId)
              ? ` · 工单：${planTaskByAgent.get(agentId)!.title}`
              : ''
          }`,
        });
      }

      // B3 — 串行路径过程卡：thinking 占位 → 流式 append → finalize + msg_foot。
      const thinkingId = gw?.nextId();
      const startedAt = Date.now();
      if (gw && thinkingId) {
        gw.emitMessage({
          id: thinkingId,
          kind: 'thinking',
          turn_id: gw.turnId,
          ts: startedAt,
          label: `${agentName} 正在思考`,
          status: 'streaming',
          agent_id: agentId,
          agent_name: agentName,
        });
      }

      // 2026-11-04「停止生成」— 串行路径同样登记进 activeDagRuns（swap 语义
      // 顺带 abort 上一轮残留），使 POST /:id/stop 能真中断 for-await 流。
      const ctrl = swapDagRun(groupId, activeDagRuns);
      let buf = '';
      // 2026-11-08 快速收尾 — 思考体累积（DAG 路径同款）：正文剥思考后为空时
      // 以思考体兜底当回复，杜绝「只有思考卡、没有回复气泡」。
      let thinkingBody = '';
      let errMsg = '';
      // 2026-11-07 流式标签剥离 — 卡体 append 前剥 <sf[:-]thinking> 定界符。
      const thinkStream = createThinkingTagStream();
      // worktree 隔离 — 该 agent 专属目录（git 仓库 workspace 时）。
      const wt = serialWt.get(agentId);
      try {
        const callable = resolveCallable(executor, { apiKey, model, workspace: wt?.dir ?? workspace });
        for await (const chunk of callable.turn({
          // 2026-11-07 记忆闭环 — soul 后附该 agent 可召回的过往经验（DM 同款）。
          system: soul + chatLessonsBlock(agentId),
          // 2026-11-07 拖拽传图 — 附件引用块并入派发上下文（串行路径，DAG 同款）；
          // 2026-11-08 视觉注入 — is_image 附件真实字节随消息进模型（DAG 同款）。
          prompt: goalWithAttachments(turnPrompt + kbText, attachments) + visionNote,
          history: turnHistory,
          images: vision.parts,
          signal: ctrl.signal,
          model,
        })) {
          if (chunk.type === 'text-delta') {
            const piece = sseWireToText(chunk.value);
            buf += piece;
            // B3 — 流式片段就地点亮（现有解析粒度 = event:text 的干净文本）。
            // 2026-11-08 — thinkStream 推进不依赖 gw（思考体累积给回复兜底）。
            if (piece) {
              const shown = thinkStream.push(piece);
              if (shown) {
                thinkingBody += shown;
                if (gw && thinkingId) {
                  gw.emitPatch({ id: thinkingId, op: 'thinking_append_body', chunk: shown });
                }
              }
            }
          } else if (chunk.type === 'thinking-delta') {
            // 2026-11-04 — API 路结构化思考通道（ApiClientCallable reasoning_content
            // → thinking-delta）：就近点亮过程卡，绝不混进最终回复 buf。
            // 2026-11-08 — 同时进思考体累积（回复兜底素材）。
            if (chunk.value) {
              thinkingBody += chunk.value;
              if (gw && thinkingId) {
                gw.emitPatch({ id: thinkingId, op: 'thinking_append_body', chunk: chunk.value });
              }
            }
          } else if (chunk.type === 'tool-use' || chunk.type === 'tool-result') {
            // G1 — 工具调用/结果就地点亮（tool_call/tool_echo 卡）；
            // 2026-11-06 检查器 — 带 agent 归属（串行路径同样可按 agent 筛）。
            emitToolChunk(gw, chunk, { agentId: agentId, agentName: agentName });
          } else if (chunk.type === 'error') {
            errMsg = chunk.error?.message ?? 'stream error';
            break;
          }
        }
      } catch (e) {
        errMsg = e instanceof Error ? e.message : String(e);
      }
      // B3 — 无论成败（含 2026-11-06 修复：abort 中断）都先收口本 agent 的
      // 过程卡。此前 abort 时直接 break 跳过收口，thinking 卡永远停在
      // streaming（刷新后回放依旧转圈）。中断 = 静默收口：finalize +
      // msg_foot done，但不发错误 raw 卡、不发聊天消息（与停止语义一致）。
      if (gw && thinkingId) {
        // 流收口：未补全的疑似标签残段丢弃，不以碎片形态进卡体。
        thinkStream.flush();
        const elapsed = Date.now() - startedAt;
        gw.emitPatch({ id: thinkingId, op: 'thinking_finalize', duration_ms: elapsed });
        if (errMsg && !ctrl.signal.aborted) {
          gw.emitMessage({
            id: gw.nextId(),
            kind: 'raw',
            turn_id: gw.turnId,
            ts: Date.now(),
            body: `[chat] ${agentName} 出错：${humanizeModelError(errMsg)}`,
            source: 'chat-gateway',
          });
        }
        gw.emitMessage({
          id: gw.nextId(),
          kind: 'msg_foot',
          turn_id: gw.turnId,
          ts: Date.now(),
          status: 'done',
          elapsed_ms: elapsed,
        });
      }

      // 2026-11-04「停止生成」— 用户经 POST /:id/stop 中断本 agent 的流：
      // 折叠成静默取消（上面已收口过程卡；不记「出错」raw 卡、不发系统
      // 消息），直接跳出 for 循环结束本轮 fan-out；gateway run 已由 stop
      // 路由经 cancelRunSession 终结。
      if (ctrl.signal.aborted) break;

      if (errMsg) {
        await pyPostMessage(groupId, {
          content: `[chat] ${agentName} 出错：${humanizeModelError(errMsg)}`,
          sender_name: 'system',
          sender_kind: 'system',
        }).catch(() => {});
        continue;
      }
      // 2026-11-04 思考剥离 — 最终聊天回复不含 <sf:thinking> 思考段
      // （思考已在过程卡实时流式展示）；全剥空 → 当空回复收口。
      // 2026-11-07 代卖协议标记 — 串行路径同款：落业务动作 + 剥标记，
      // [build-team]/[dispatch] 流程动作在挂钩点执行（总经理主控）。
      // 2026-11-08 图→博文流水线 — 草拟回合防线与 DAG 路径同款（[post]→[draft]）。
      // 2026-11-08 快速收尾 — 回复兜底（DAG 路径同款）：正文剥思考后为空时
      // 取思考体当回复。
      const replySource = stripThinking(buf).trim() || thinkingBody.trim();
      const serialDraftTurn = craftScoped && isPostDraftRequest(prompt);
      const serialText = serialDraftTurn
        ? convertPostMarkersToDraft(replySource)
        : replySource;
      const appliedSerial = await applyCraftMarkers(serialText, { scoped: craftScoped });
      await runCraftFlowActions(group, appliedSerial.actions, { executor, model, headers }, attachments, serialDraftTurn);
      const reply = appliedSerial.cleaned.trim();
      if (!reply) {
        await pyPostMessage(groupId, {
          content: `[chat] ${agentName} 返回空回复。`,
          sender_name: 'system',
          sender_kind: 'system',
        }).catch(() => {});
        continue;
      }
      // agent 最终回复仍走 pyPostMessage（聊天消息路径零变化）。
      // 2026-10-31 — 补 agent_id 透传（DAG 路径 U0 同款）：前端 agentById
      // 按 agent_id 命中 DiceBear 头像，缺省 → 字母色块兜底（头像「不绑定」根因）。
      await pyPostMessage(groupId, {
        content: reply,
        sender_name: agentName,
        sender_kind: 'agent',
        agent_id: agentId,
      }).catch(() => {});
      // 记忆交接沉淀收集器 — 串行路径同款（执行序）。
      serialSpeakers.push({
        id: agentId,
        name: agentName,
        excerpt: reply.replace(/\s+/g, ' ').trim().slice(0, 160),
      });
      // 串行路径同样「干完即提交」— worktree 产物 + 证据卡。
      if (wt) {
        await commitAndEvidence(gw, wt, { agentId: agentId, agentName: agentName }, prompt);
      }
    }
    // 仅当注册表里仍是本轮 controller 时才删（避免误删后来者；DAG 路径 finally 同款）。
    const serialCtrl = activeDagRuns.get(groupId);
    if (serialCtrl && !serialCtrl.signal.aborted) activeDagRuns.delete(groupId);
    // 串行路径收尾：各 agent 分支按执行序并入集成分支。
    await integrateAndReport(gw, groupId, workspace, serialRunKey, agentIds, serialWt);
    // 记忆交接沉淀（2026-11-05 GrokBot 对齐）— 多 agent 串行回合同样落交接包。
    // turn_seq 用负数时间戳锚（串行路径无 hop turnSeq；shift_id 幂等锚粒度到轮）。
    sinkRoundHandoff({
      groupId,
      turnSeq: -Date.now(),
      goal: serialPrompt,
      speakers: serialSpeakers,
    });
    gw?.finish('succeeded');
  } catch (e) {
    // 未捕获异常：过程流以 raw 卡可见地收口，run 标 failed；异常继续上抛
    // （调用方 fire-and-forget 的 .catch 负责 console.warn，行为不变）。
    if (gw) {
      const msg = e instanceof Error ? e.message : String(e);
      gw.emitMessage({
        id: gw.nextId(),
        kind: 'raw',
        turn_id: gw.turnId,
        ts: Date.now(),
        body: `[chat-gateway] fan-out 异常：${msg}`,
        source: 'chat-gateway',
      });
      gw.finish('failed');
    }
    throw e;
  }
}

// ── B2 · GET /api/groups/:id/timeline ────────────────────────────────────────
// 统一消息读路径 (unified-conversation-core-plan-2026-06-11 §B2)：把一个群的
// 完整会话历史聚合成前端 Timeline 渲染器可直接消费的 TimelineMessage[]：
//   a) 聊天消息（Python 群记录 MessageItem）→ chatMessagesToTimeline 适配
//      （user→user_turn / agent→assistant_text / system→raw，turn_id 按 user
//      消息切段）；
//   b) B1 互链 conversation 下每个 run session 的事件日志（run-event-bus 内存
//      + run-event-store 落盘，经 getRunReplay 统一取出）→ replayTimeline
//      重放 message/message-patch 得到最终 TimelineMessage[]；
//   c) 两路按 ts 升序归并；先全量不分页，上限 500 条（保最新）+ truncated 标记。
// 响应: { group_id, messages: TimelineMessage[], runs: [{session_id,status}], truncated }

/** 全量上限：超过只保留最新的 500 条（truncated: true）。 */
const TIMELINE_MAX_MESSAGES = 500;

// ── POST /api/groups/:id/stop ────────────────────────────────────────────────
// 2026-11-04「停止生成」（用户反馈：点暂停按钮对话停不下来，不合理）—
// 主动取消该群当前 fan-out 轮：abort fan-out AbortController（DAG 停止调度
// 后续节点 / 串行 for-await 断流）+ cancelRunSession 终结互链 conversation 下
// 所有 running gateway run（timeline runs 立即翻终态 → 前端 busy 解除）。
// 幂等：无在跑轮 → stopped=false，前端照样本地退出 busy。
router.post('/:id/stop', (req: Request, res: Response) => {
  const groupId = req.params.id;
  const stopped = stopGroupFanout(groupId);
  res.json({ group_id: groupId, stopped });
});

/**
 * GET /api/groups/:id/hops — agent 间交接记录查询（2026-11-05，OpenBot hop 模型）。
 * ?turns=N 取最近 N 个回合（默认 1，上限 20）；?all=1 展开为逐条 hop 数组。
 * 默认返回紧凑摘要文本（与回合结束 postMessage 同源，前端可直接渲染）。
 */
router.get('/:id/hops', (req: Request, res: Response) => {
  void (async () => {
    const groupId = req.params.id;
    const turns = Math.min(Math.max(Number(req.query.turns ?? 1) || 1, 1), 20);
    const hops = listRecentHops(groupId, turns);
    const turnSeqs = [...new Set(hops.map((h) => h.turn_seq))];
    if (req.query.all === '1') {
      res.json({ group_id: groupId, turns: turnSeqs.sort((a, b) => b - a), hops });
      return;
    }
    const summaries = turnSeqs
      .sort((a, b) => b - a)
      .map((t) => ({ turn_seq: t, summary: summarizeHops(groupId, t) }))
      .filter((s) => s.summary);
    res.json({ group_id: groupId, turns: turnSeqs.sort((a, b) => b - a), summaries });
  })().catch((e) => {
    const msg = e instanceof Error ? e.message : String(e);
    if (!res.headersSent) {
      res.status(500).json({ error: { code: 'HOPS_FAILED', message: msg } });
    }
  });
});

router.get('/:id/timeline', (req: Request, res: Response) => {
  void (async () => {
    const groupId = req.params.id;
    const group = await pyGet<GroupRecord>(`/api/groups/${encodeURIComponent(groupId)}`);
    if (!group) {
      // pyGet 把「Python 没起」和「群不存在」都折叠成 null；对读路径两者的
      // 用户语义一致（拿不到这个群）——用 404 + 提示语区分排查方向。
      res.status(404).json({
        error: {
          code: 'GROUP_NOT_FOUND',
          message: `group ${groupId} not found (or Python backend unreachable)`,
        },
      });
      return;
    }

    // a) 聊天消息适配。
    const chatMessages = chatMessagesToTimeline(group.messages ?? []);

    // b) 互链 run 的过程消息归并。无互链 conversation = 纯聊天群，runs 为空。
    const runs: Array<{ session_id: string; status: string }> = [];
    const runMessages: TimelineMessage[] = [];
    const conv = getConversationByGroup(groupId);
    if (conv) {
      for (const sessionId of listSessionsByConversation(conv.conversation_id)) {
        const replay = getRunReplay(sessionId);
        if (!replay) {
          // session 记录在、事件日志已被 TTL 清理：run 列表仍可见，过程消息缺位。
          runs.push({ session_id: sessionId, status: 'idle' });
          continue;
        }
        runs.push({ session_id: sessionId, status: replay.status });
        // 任务归属标签（2026-11-08 任务面板）：run replay 消息带 session_id，前端按任务切片
        runMessages.push(
          ...replayTimeline(replay.events).map((m) => ({ ...m, session_id: sessionId })),
        );
      }
    }

    // c) ts 升序归并。sort 稳定：同 ts 时聊天消息先于 run 消息（拼接顺序）。
    const merged = [...chatMessages, ...runMessages].sort((a, b) => a.ts - b.ts);
    const truncated = merged.length > TIMELINE_MAX_MESSAGES;
    const messages = truncated ? merged.slice(merged.length - TIMELINE_MAX_MESSAGES) : merged;

    res.json({ group_id: groupId, messages, runs, truncated });
  })().catch((e) => {
    const msg = e instanceof Error ? e.message : String(e);
    if (!res.headersSent) {
      res.status(500).json({ error: { code: 'TIMELINE_FAILED', message: msg } });
    }
  });
});

// ── GET /api/groups/:id/dag — 群「当前/最近一次运行」的 DAG ─────────────────
// 取数优先级（契约）：
//   1. run replay/graph —— 互链 conversation 下最近一次仍有事件日志的 run，
//      buildDaemonRunGraph 折叠出执行图（plan 任务节点优先；无 plan 退到
//      步骤/工具节点并截断 30，防工具链撑爆前端）；
//   2. team dag —— 无可用 run 时回落 group.team_id 的编排定义（loadTeamForRun，
//      与 runFanout 执行路径同一数据源，policy_matrix 即前端 PolicyMatrix）；
//   3. 群成员空图 —— 纯聊天群（无 run 无 team）：成员即节点、无边。
// 出参对齐前端 SfTeamDag（frontend/src/chat-api.ts）——**裸对象**（getGroupDag
// 用 apiFetch 直读顶层 edges，不做 {data} 解包）：
//   { team_id, name, members, edges:[{source,target,mode,data:{mode}}],
//     resolved_agents:[{id,title,sub?}], policy, source, run_id? }
// 附加字段（source/run_id/errors）仅调试用，前端 normalizeDag 忽略。
// 归属校验：groupAccessGuard 的 /:id/** 已统一把关（非本人 404，此处不再重复判）。

/** TeamEdgeV1.kind → 前端 SfDagEdge.mode（direct|approve|conditional；原 kind 留 data.mode）。 */
function dagEdgeMode(kind: string | undefined): string {
  if (kind === 'approve') return 'approve';
  if (kind === 'conditional') return 'conditional';
  return 'direct'; // sequential / parallel / 未知 → direct
}

/** 成员展示名片段解析（fail-soft：agent 读不到就用 id 兜底；与 runFanout roster 同法）。 */
async function resolveDagAgents(
  ids: string[],
): Promise<Array<{ id: string; title: string; sub?: string }>> {
  const out: Array<{ id: string; title: string; sub?: string }> = [];
  for (const id of ids) {
    let title = id;
    let sub: string | undefined;
    try {
      const a = await pyGet<AgentRecord>(`/api/agents/${encodeURIComponent(id)}`);
      if (a?.name) title = a.name;
      if (a?.soul) sub = a.soul.split('\n').find((l) => l.trim())?.trim();
    } catch { /* id 兜底 */ }
    out.push(sub ? { id, title, sub } : { id, title });
  }
  return out;
}

router.get('/:id/dag', (req: Request, res: Response) => {
  void (async () => {
    const groupId = req.params.id;
    const group = await pyGet<GroupRecord>(`/api/groups/${encodeURIComponent(groupId)}`);
    if (!group) {
      // 与 timeline 同一语义：pyGet 把「Python 没起」与「群不存在」折叠成 null。
      res.status(404).json({
        error: {
          code: 'GROUP_NOT_FOUND',
          message: `group ${groupId} not found (or Python backend unreachable)`,
        },
      });
      return;
    }

    // ── 1) run replay/graph：最近一次有事件日志的 run 折叠成执行图 ─────────
    const conv = getConversationByGroup(groupId);
    if (conv) {
      const goals = new Map<string, string>();
      try {
        for (const r of listRunIndexByConversation(conv.conversation_id)) {
          goals.set(r.session_id, r.goal);
        }
      } catch { /* sqlite 不可用 → name 兜底 run_id */ }
      // listSessionsByConversation 最近更新在前 —— 第一个可重放的就是「当前/最近一次运行」。
      for (const sessionId of listSessionsByConversation(conv.conversation_id)) {
        const replay = getRunReplay(sessionId);
        if (!replay) continue;
        const graph = buildDaemonRunGraph(sessionId, replay);
        // plan 任务节点是「任务级 DAG」的自然单位；纯步骤 run（无 plan_card）
        // 退到全节点并截断。
        const taskNodes = graph.nodes.filter((n) => n.kind === 'task');
        const nodes = taskNodes.length > 0 ? taskNodes : graph.nodes.slice(0, 30);
        if (nodes.length === 0) continue;
        const keep = new Set(nodes.map((n) => n.id));
        let edges = graph.edges
          .filter((e) => keep.has(e.from_id) && keep.has(e.to_id))
          .map((e) => ({
            source: e.from_id,
            target: e.to_id,
            mode: 'direct',
            data: { mode: e.type },
          }));
        if (edges.length === 0 && nodes.length > 1) {
          // 任务节点之间的边被步骤隔断 → 按执行顺序补链（与 buildDaemonRunGraph 同策略）。
          edges = nodes.slice(1).map((n, i) => ({
            source: nodes[i]!.id,
            target: n.id,
            mode: 'direct',
            data: { mode: 'control_flow' },
          }));
        }
        res.json({
          team_id: group.team_id ?? groupId,
          name: goals.get(sessionId) || `run ${sessionId}`,
          members: nodes.map((n) => n.id),
          edges,
          resolved_agents: nodes.map((n) => ({ id: n.id, title: n.label })),
          policy: null,
          source: 'run_graph',
          run_id: sessionId,
        });
        return;
      }
    }

    // ── 2) team dag 回落：编排定义（成员 + 边 + 策略矩阵）─────────────────
    if (group.team_id) {
      const { team, errors } = loadTeamForRun(group.team_id);
      if (team && team.members.length > 0) {
        res.json({
          team_id: group.team_id,
          name: team.name ?? group.team_id,
          members: team.members,
          edges: team.edges.map((e) => ({
            source: e.from,
            target: e.to,
            mode: dagEdgeMode(e.kind),
            data: { mode: e.kind ?? 'sequential' },
          })),
          resolved_agents: await resolveDagAgents(team.members),
          policy: team.policy_matrix ?? null,
          source: 'team',
          errors,
        });
        return;
      }
      if (errors.length > 0) {
        console.warn(`[groups-chat] dag: team ${group.team_id} load failed:`, errors.join('; '));
      }
    }

    // ── 3) 纯聊天群空图：成员即节点、无边 ────────────────────────────────
    const members = group.agent_ids ?? [];
    res.json({
      team_id: groupId,
      name: '',
      members,
      edges: [],
      resolved_agents: members.length > 0 ? await resolveDagAgents(members) : [],
      policy: null,
      source: 'group',
    });
  })().catch((e) => {
    const msg = e instanceof Error ? e.message : String(e);
    if (!res.headersSent) {
      res.status(500).json({ error: { code: 'DAG_FAILED', message: msg } });
    }
  });
});

/**
 * POST /api/groups/:id/messages — intercept chat send.
 *
 * Persists the user message, returns 201 immediately (front-end已乐观更新),
 * then runs the reply fan-out in the background (replies stream back via the
 * Python SSE bus). Only `sender_kind:'user'` is intercepted for reply
 * generation; non-user writes are persisted and returned as-is.
 */
router.post('/:id/messages', (req: Request, res: Response) => {
  void (async () => {
    const groupId = req.params.id;
    const body = (req.body ?? {}) as {
      content?: string;
      sender_name?: string;
      sender_kind?: string;
      executor?: string;
      model?: string;
      knowledge_pack_ids?: unknown;
      attachments?: unknown;
    };
    const senderKind = body.sender_kind ?? 'user';
    const content = typeof body.content === 'string' ? body.content : '';
    // 2026-11-07 拖拽传图 — 随行附件清洗（coerceAttachments：字段清洗/上限 9，
    // 与 composer 和 run-sessions 同一实现）；空/缺省不落库不下发。
    const attachments = coerceAttachments(body.attachments);

    try {
      // Persist the incoming message via Python. For user messages set the
      // suppress header so Python's own bridge doesn't ALSO reply (we own it).
      const created = await pyPostMessage(
        groupId,
        {
          content,
          sender_name: body.sender_name ?? (senderKind === 'user' ? 'user' : 'agent'),
          sender_kind: senderKind,
          ...(attachments && attachments.length > 0 ? { attachments } : {}),
        },
        { noDispatch: senderKind === 'user' },
      );
      // 2026-11-07 拖拽传图 — 201 响应体保证带 attachments（持久层已 echo 时
      // 覆盖为同一份清洗结果，前端契约不依赖后端模式）。
      res.status(201).json(
        attachments && attachments.length > 0 && created && typeof created === 'object'
          ? { ...(created as Record<string, unknown>), attachments }
          : created,
      );
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      res.status(502).json({ error: { code: 'PERSIST_FAILED', message: msg } });
      return;
    }

    // Only user messages trigger an agent reply.
    if (senderKind !== 'user') return;

    // Executor selection. Priority:
    //   1. Explicit body.executor — the UI model picker's choice always wins
    //      (e.g. `byok:zhipu`, `anthropic-direct`, `cli:codex`).
    //   2. 2026-11-04 默认回退修正 — 设置页配了 enabled BYOK key 的 provider
    //      优先于 cli:claude。旧行为无脑默认 cli:claude：CLI 未登录/挂起时群聊
    //      thinking 卡永远 streaming（无超时无报错，「不能正常对话」根因之一）。
    //      改法：settings/byok 里有 enabled+key 的 provider（如 zhipu）时，
    //      默认 `byok:<id>`（key 由 resolveProviderKey 的 settings 分支解析），
    //      API 直连失败也会以 error chunk 可见地报错，不再静默卡死。
    //   3. cli:claude — 最后兜底（CLI 自带 OAuth 认证时仍是好选择）。
    const executor =
      typeof body.executor === 'string' && body.executor.trim()
        ? body.executor.trim()
        : pickDefaultExecutor();
    const model =
      typeof body.model === 'string' && body.model.trim() ? body.model.trim() : undefined;

    // Fire-and-forget; replies reach the browser via Python SSE.
    // userText 原文透传（@ 提及解析用）——persisted 记录即 content，直接用它
    // 避免 runFanout 二次反查（时序上 group.messages 已含本条）。
    // 2026-11-05 审批门 — 该群有挂起的节点审批且本条消息是明确批/拒语义 →
    // 先把决定送达（不改聊天主链路：消息照常持久化； fan-out 照常，若用户
    // 批/拒后还想派新活，这条消息本身就是新一轮）。
    tryResolveApprovalFromText(groupId, content);
    // 2026-11-08 图→博文流水线 — 草稿确认/放弃与审批门挂起期的决定消息在此
    // 消费，不再发起新一轮 fan-out（swapDagRun 会把流水线挂起的审批门当「上
    // 一轮」掐掉）。非决定消息/无流水线 → false 照常派发（fan-out 打断挂起
    // 审批门时流水线按「被拒绝或被打断」收场并提示重进）。
    if (await craftPostPipeline.takeInput(groupId, content)) return;
    // 对话框知识库（2026-11-06）— 记忆库 pack id 透传给 fan-out（每轮检索注入）。
    // 2026-11-07 拖拽传图 — 附件透传给 fan-out（goalWithAttachments 注入派发上下文）。
    void runFanout(
      groupId,
      executor,
      model,
      req.headers,
      content,
      coercePackIds(body.knowledge_pack_ids),
      attachments,
    ).catch((e) => {
      // eslint-disable-next-line no-console
      console.warn('[groups-chat] fanout failed:', e);
      // 错误人话化收尾（2026-11-09 OpenBot）：派发失败必须在聊天里可见收场——
      // 此前只留一条服务端 warn，用户端转圈会一直等一条永远不会来的回复。
      void pyPostMessage(groupId, {
        content: `[chat] 本轮任务派发失败：${humanizeModelError(e instanceof Error ? e.message : String(e))}。可以重发消息重试。`,
        sender_name: 'system',
        sender_kind: 'system',
      }).catch(() => {});
    });
  })();
});

/**
 * POST /api/groups/:id/approvals/:nodeId — 显式审批决定（2026-11-05，决定路径①）。
 * body: { decision: 'approve' | 'reject' }。
 * 命中挂起 → resolve 执行器 promise（执行器会补系统留痕消息 + plan_card blocked）；
 * 未命中 → 409（已决定/超时/无此挂起）。
 * 处理器导出供回归测试直打（不起真 Express）。
 */
export function approvalDecisionHandler(
  req: { params: { id: string; nodeId: string }; body?: unknown },
  res: { status(code: number): { json(body: unknown): void }; json(body: unknown): void },
): void {
  const groupId = req.params.id;
  const nodeId = req.params.nodeId;
  const decision = ((req.body ?? {}) as { decision?: unknown }).decision;
  if (decision !== 'approve' && decision !== 'reject') {
    res.status(400).json({
      error: { code: 'BAD_DECISION', message: "decision must be 'approve' or 'reject'" },
    });
    return;
  }
  const key = `${groupId}:${nodeId}`;
  const entry = pendingApprovals.get(key);
  if (!entry) {
    res.status(409).json({
      error: { code: 'NO_PENDING_APPROVAL', message: `no pending approval for node ${nodeId} in group ${groupId}` },
    });
    return;
  }
  pendingApprovals.delete(key);
  try {
    entry.resolve(decision === 'approve' ? 'approved' : 'rejected');
  } catch { /* resolver 已 settle — 幂等 */ }
  res.json({ group_id: groupId, node_id: nodeId, decision });
}

router.post('/:id/approvals/:nodeId', approvalDecisionHandler);

/**
 * GET /api/groups/:id/approvals/pending — 挂起审批可见化（2026-11-09）。
 * Node 内存挂起（chat DAG approve 边 + 图→博文流水线审批门）与 Python runtime
 * 注册表（run-sessions 体系）合并返回，前端审批 Tab 才能点亮批/拒按钮。
 * 此前 Node 无此 GET 路由 → 落 proxyFallback 打 Python 单源 → chat DAG 的挂起
 * 永远不可见（「审批门静默挂 30 分钟」根因）。Python 侧拉取 fail-soft：不可达
 * 只影响合并项，Node 侧条目照常返回。
 * 处理器导出供回归测试直打（不起真 Express）。
 */
export function approvalPendingHandler(
  req: { params: { id: string } },
  res: { json(body: unknown): void },
): void {
  void (async () => {
    const groupId = req.params.id;
    const items = listPendingApprovalItems(groupId);
    let pyItems: unknown[] = [];
    try {
      const py = await pyGet<unknown>(
        `/api/groups/${encodeURIComponent(groupId)}/approvals/pending`,
      );
      if (Array.isArray(py)) pyItems = py;
      else if (py && typeof py === 'object' && Array.isArray((py as { items?: unknown }).items)) {
        pyItems = (py as { items: unknown[] }).items;
      }
    } catch { /* Python 侧不可达只影响合并项 */ }
    res.json({ items: [...items, ...pyItems] });
  })();
}

router.get('/:id/approvals/pending', approvalPendingHandler);

export { router as groupsChatRouter };
export default router;

/**
 * 测试专用薄导出 — runFanout 原样透传（mention 定向派活路由行为测试用，
 * 避免为驱动 fan-out 而起真 HTTP / 真 Python）。生产代码不要调用。
 */
export const runFanoutAsync = runFanout;
